import { API_BASE_URL } from "../../constants.js";
import getAuthStatus from "./getAuthStatus.js";

const MARK_ACTIVE_ALARM_NAME = "betterblox-mark-active-user";

class MarkActiveUserService {
  constructor() {
    this.alarmListener = null;
    this.isInitialized = false;
    this.INTERVAL_MINUTES = 30;
  }

  async initialize() {
    if (this.isInitialized) {
      console.log("[MarkActiveUser] Already initialized");
      return;
    }

    console.log("[MarkActiveUser] Initializing user activity tracking");

    try {
      // Send initial presence update
      await this.sendActivityUpdate();

      // chrome.alarms survives MV3 service-worker unloads; setInterval does not.
      chrome.alarms.create(MARK_ACTIVE_ALARM_NAME, {
        periodInMinutes: this.INTERVAL_MINUTES,
      });
      this.alarmListener = async (alarm) => {
        if (alarm.name !== MARK_ACTIVE_ALARM_NAME) return;
        try {
          await this.sendActivityUpdate();
        } catch (error) {
          console.error("[MarkActiveUser] Error in alarm update:", error);
        }
      };
      chrome.alarms.onAlarm.addListener(this.alarmListener);

      this.isInitialized = true;
      console.log(`[MarkActiveUser] Initialized with ${this.INTERVAL_MINUTES} minute intervals`);
    } catch (error) {
      console.error("[MarkActiveUser] Failed to initialize:", error);
    }
  }

  async getCurrentUserData() {
    try {
      // Use getAuthStatus like friendsService does
      const authData = await getAuthStatus.getAuthData(true);

      if (!authData || !authData.id || !authData.name) {
        console.log("[MarkActiveUser] User not authenticated");
        return null;
      }

      return {
        id: authData.id,
        username: authData.name,
      };
    } catch (error) {
      console.error("[MarkActiveUser] Error fetching current user:", error);
      return null;
    }
  }

  async sendActivityUpdate() {
    const currentUser = await this.getCurrentUserData();

    if (!currentUser) {
      console.log("[MarkActiveUser] No current user to update");
      return;
    }

    try {
      const response = await fetch(`${API_BASE_URL}/api/users/mark-active`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          userId: currentUser.id,
          username: currentUser.username,
        }),
      });

      if (response.ok) {
        const result = await response.json();
        if (result.success) {
          console.log(`[MarkActiveUser] Successfully marked ${currentUser.username} as active`);
        } else {
          console.error("[MarkActiveUser] API returned success: false");
        }
      } else {
        console.error(`[MarkActiveUser] Failed to mark user active: ${response.status}`);
      }
    } catch (error) {
      console.error("[MarkActiveUser] Error sending activity update:", error);
    }
  }

  // Manual trigger for testing
  async triggerUpdate() {
    console.log("[MarkActiveUser] Manual activity update triggered");
    await this.sendActivityUpdate();
  }

  // Stop the service
  stop() {
    chrome.alarms.clear(MARK_ACTIVE_ALARM_NAME);
    if (this.alarmListener) {
      chrome.alarms.onAlarm.removeListener(this.alarmListener);
      this.alarmListener = null;
    }
    console.log("[MarkActiveUser] Stopped");
    this.isInitialized = false;
  }

  // Get current status
  getStatus() {
    return {
      isInitialized: this.isInitialized,
      intervalMinutes: this.INTERVAL_MINUTES,
      hasInterval: !!this.alarmListener,
    };
  }

  // Get current user (similar to friendsService pattern)
  async getCurrentUser() {
    return await this.getCurrentUserData();
  }
}

// Export singleton instance
export default new MarkActiveUserService();
