import { FAST_API_BASE_URL } from "../../constants.js";
import { browserAPI } from "../../utils/browserAPI.js";
import { parseRetryAfterMs } from "../../utils/retryAfter.js";

const JOIN_GAME_DEFAULT_RETRY_MS = 5000;

class ServerInfoManager {
  constructor() {
    this.SERVER_URL = FAST_API_BASE_URL;
    this.DATACENTER_CACHE_KEY = "betterblox_datacenters_cache";
    this.CACHE_EXPIRY_KEY = "betterblox_datacenters_cache_expiry";
    this.CACHE_DURATION = 24 * 60 * 60 * 1000; // 24 hours
    this.SHORT_CACHE_DURATION = 15 * 1000; // 15 seconds
    this.CLIENT_LOCATION_KEY = "betterblox_client_location";
    /** Latest join-game task id per tab (content script); bumps invalidate in-flight work */
    this.joinGameTaskIdByTabId = new Map();
  }

  _joinGameTabId(sender) {
    return sender?.tab?.id ?? null;
  }

  _isJoinGameTaskStale(tabId, taskId) {
    if (tabId == null || taskId == null) return false;
    const latest = this.joinGameTaskIdByTabId.get(tabId);
    if (latest === undefined) return false;
    return latest !== taskId;
  }

  _joinGameStalePayload(tabId, taskId) {
    if (this._isJoinGameTaskStale(tabId, taskId)) {
      return { abortedStaleTask: true };
    }
    return null;
  }

  /** Sleep in short slices so a bumped task id can abort long Retry-After waits */
  async _sleepJoinGameUnlessStale(ms, tabId, taskId) {
    const slice = 400;
    let remaining = ms;
    while (remaining > 0) {
      if (this._isJoinGameTaskStale(tabId, taskId)) return;
      const step = Math.min(slice, remaining);
      await new Promise((r) => setTimeout(r, step));
      remaining -= step;
    }
  }

  init() {
    if (chrome.tabs?.onRemoved) {
      chrome.tabs.onRemoved.addListener((tabId) => {
        this.joinGameTaskIdByTabId.delete(tabId);
      });
    }

    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      if (message.type === "SET_JOIN_GAME_TASK_ID") {
        const tabId = this._joinGameTabId(sender);
        if (tabId != null && message.taskId != null) {
          this.joinGameTaskIdByTabId.set(tabId, message.taskId);
        }
        sendResponse({ ok: true });
        return false;
      }
      if (message.type === "GET_DATACENTERS") {
        (async () => {
          const datacenters = await this.getDatacenters();
          console.log(
            "[SERVER INFO] Datacenters fetched from server and cached",
          );
          sendResponse(datacenters);
        })();
        return true;
      }
      if (message.type === "GET_GAMEJOIN_DATA") {
        (async () => {
          const tabId = this._joinGameTabId(sender);
          const taskId = message.data?.taskId ?? null;
          sendResponse(
            await this.getGameJoinData(
              message.data.placeId,
              message.data.serverId,
              taskId,
              tabId,
            ),
          );
        })();
        return true;
      }
      if (message.type === "GET_CLIENT_LOCATION") {
        (async () => {
          const location = await this.getClientLocation();
          sendResponse(location);
        })();
        return true;
      }
    });
  }

  async getDatacenters() {
    try {
      // Check if we have recent cached data (less than 15 seconds old)
      const cachedData = await this.getCachedDatacenters();

      if (cachedData && this.isCacheRecent(cachedData)) {
        console.log(
          "[SERVER INFO] Using recent cached datacenter data (< 15 seconds)",
        );
        return cachedData.data;
      }

      // Try to fetch from server
      const response = await fetch(`${this.SERVER_URL}/servers/datacenters`);

      if (response.ok) {
        const serverData = await response.json();

        // Cache the successful response
        await this.cacheDatacenters(serverData);
        console.log("[SERVER INFO] Datacenters fetched from server and cached");

        return serverData;
      } else {
        throw new Error(`Server responded with status: ${response.status}`);
      }
    } catch (error) {
      console.warn("[SERVER INFO] Failed to fetch from server:", error.message);

      // Fallback to cached data (even if older than 15 seconds)
      const cachedData = await this.getCachedDatacenters();

      if (cachedData) {
        console.log("[SERVER INFO] Using cached datacenter data as fallback");
        return cachedData.data;
      } else {
        console.error("[SERVER INFO] No cached data available, returning null");
        return null;
      }
    }
  }

  /**
   * Cache datacenter data to localStorage
   */
  async cacheDatacenters(data) {
    try {
      const cacheData = {
        data: data,
        timestamp: Date.now(),
      };

      await browserAPI.storage.local.set({
        [this.DATACENTER_CACHE_KEY]: cacheData,
      });
    } catch (error) {
      console.warn("[SERVER INFO] Failed to cache datacenters:", error);
    }
  }

  /**
   * Get cached datacenter data from localStorage
   */
  async getCachedDatacenters() {
    try {
      const result = await browserAPI.storage.local.get([
        this.DATACENTER_CACHE_KEY,
      ]);
      const cacheData = result[this.DATACENTER_CACHE_KEY];

      if (!cacheData) {
        return null;
      }

      // Check if cache is expired (24 hours)
      const now = Date.now();
      const cacheAge = now - cacheData.timestamp;

      if (cacheAge > this.CACHE_DURATION) {
        console.log(
          "[SERVER INFO] Cached datacenter data expired, but using as fallback",
        );
        // Don't return null even if expired - use stale data as fallback
      }

      return cacheData; // Return full cache object with timestamp
    } catch (error) {
      console.warn("[SERVER INFO] Failed to get cached datacenters:", error);
      return null;
    }
  }

  /**
   * Check if cached data is recent (less than 15 seconds old)
   */
  isCacheRecent(cacheData) {
    if (!cacheData || !cacheData.timestamp) {
      return false;
    }

    const now = Date.now();
    const cacheAge = now - cacheData.timestamp;

    return cacheAge < this.SHORT_CACHE_DURATION;
  }

  /**
   * Store client location to chrome storage
   */
  async storeClientLocation(location) {
    try {
      if (!location || !location.latitude || !location.longitude) {
        console.warn("[SERVER INFO] Invalid location data provided");
        return false;
      }

      const locationData = {
        latitude: location.latitude,
        longitude: location.longitude,
        timestamp: Date.now(),
      };

      await browserAPI.storage.local.set({
        [this.CLIENT_LOCATION_KEY]: locationData,
      });

      console.log("[SERVER INFO] Client location stored:", locationData);
      return true;
    } catch (error) {
      console.warn("[SERVER INFO] Failed to store client location:", error);
      return false;
    }
  }

  /**
   * Get client location from chrome storage
   */
  async getClientLocation() {
    try {
      const result = await browserAPI.storage.local.get([
        this.CLIENT_LOCATION_KEY,
      ]);
      const locationData = result[this.CLIENT_LOCATION_KEY];

      if (!locationData) {
        console.log("[SERVER INFO] No client location found in storage");
        return null;
      }

      console.log(
        "[SERVER INFO] Retrieved client location from storage:",
        locationData,
      );
      return {
        latitude: locationData.latitude,
        longitude: locationData.longitude,
      };
    } catch (error) {
      console.warn("[SERVER INFO] Failed to get client location:", error);
      return null;
    }
  }


  async getGameJoinData(placeId, gameId, taskId, tabId) {
    const maxAttempts = 3;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      const staleOut = this._joinGameStalePayload(tabId, taskId);
      if (staleOut) return staleOut;

      try {
        const serverInfo = await fetch(
          `https://gamejoin.roblox.com/v1/join-game-instance`,
          {
            method: "POST",
            headers: {
              Accept: "*/*",
              "Accept-Encoding": "gzip, deflate, br, zstd",
              "Accept-Language": "en,en-US;q=0.9",
              Referer: `https://www.roblox.com/games/${placeId}/`,
              Origin: "https://www.roblox.com",
              "User-Agent": "Roblox",
            },
            body: JSON.stringify({
              placeId,
              gameId,
              gameJoinAttemptId: gameId,
              joinOrigin: "RobloxApp",
            }),
            credentials: "include",
          },
        );

        const staleAfterFetch = this._joinGameStalePayload(tabId, taskId);
        if (staleAfterFetch) return staleAfterFetch;

        if (serverInfo.status === 429) {
          const waitMs = parseRetryAfterMs(serverInfo, JOIN_GAME_DEFAULT_RETRY_MS);
          console.warn(
            `[SERVER INFO] getGameJoinData 429 (attempt ${attempt}/${maxAttempts}), waiting ${waitMs}ms`,
          );
          if (attempt < maxAttempts) {
            await this._sleepJoinGameUnlessStale(waitMs, tabId, taskId);
            continue;
          }
          return {
            error: "Too many requests (429)",
            status: 429,
            waitTime: serverInfo.headers.get("retry-after"),
          };
        }

        const data = await serverInfo.json();
        const staleAfterJson = this._joinGameStalePayload(tabId, taskId);
        if (staleAfterJson) return staleAfterJson;

        const { joinScript } = data;

        if (!joinScript) {
          const staleBeforeReturn = this._joinGameStalePayload(tabId, taskId);
          if (staleBeforeReturn) return staleBeforeReturn;
          return {
            data,
            status: serverInfo.status,
            waitTime: serverInfo.headers.get("retry-after"),
            queuePosition: data.queuePosition || 0, // Include queue position even when no joinScript
          };
        }

        const location = {
          latitude: null,
          longitude: null,
        };

        if (joinScript.SessionId) {
          const sessionId = JSON.parse(joinScript.SessionId);
          location.latitude = sessionId.Latitude;
          location.longitude = sessionId.Longitude;

          // Store client location if we have valid coordinates
          if (location.latitude && location.longitude) {
            console.log(
              "[SERVER INFO] Storing client location from game join data",
            );
            await this.storeClientLocation(location);
          }
        }

        const staleAfterLocation = this._joinGameStalePayload(tabId, taskId);
        if (staleAfterLocation) return staleAfterLocation;

        const connection = joinScript.UdmuxEndpoints?.[0] || null;

        if (!connection || !connection.Address) {
          console.error("No connection address found");
          const staleNoAddr = this._joinGameStalePayload(tabId, taskId);
          if (staleNoAddr) return staleNoAddr;
          return {
            data,
            status: serverInfo.status,
            waitTime: serverInfo.headers.get("retry-after"),
            queuePosition: data.queuePosition || 0, // Include queue position even when no joinScript
          };
        }
        const staleFinal = this._joinGameStalePayload(tabId, taskId);
        if (staleFinal) return staleFinal;

        const response = {
          clientData: location,
          ip: connection.Address,
          datacenterId: joinScript.DataCenterId,
          placeVersion: joinScript.PlaceVersion || null,
          queuePosition: data.queuePosition || 0, // Include queue position if available
        };

        return response;
      } catch (error) {
        console.error("Failed to fetch server data:", error);
        return null;
      }
    }
  }
}

const serverInfoManager = new ServerInfoManager();
export default serverInfoManager;
