/**
 * Local playtime history (heatmap / top games / recent sessions).
 *
 * The server deliberately keeps NO per-chunk collection anymore — it stores only
 * the authoritative totals (xp, lifetime minutes, daily cap). The granular history
 * that powers the dashboard lives HERE, client-side, in chrome.storage. These are
 * pure helpers; the owner (playtimeXpService) handles persistence.
 *
 * Raw shape (small + bounded):
 *   {
 *     v: 1,
 *     days:  { "YYYY-MM-DD": { minutes, xp } },                      // heatmap + week + today
 *     games: { "<placeId>": { minutes, xp, sessions, lastPlayed } }, // top games
 *     sessions: [ { sessionId, placeId, gameName, minutes, xp, start, end } ] // recent (newest first)
 *   }
 *
 * buildDashboard() projects that into the exact fields the /playtime dashboard
 * reads, so the host (extension OR launcher) answers GET_PLAYTIME_HISTORY with a
 * ready-to-merge payload and the theme just spreads it onto the server totals.
 */

const DAY_MS = 86400000;
const KEEP_DAYS = 180; // heatmap window; older day buckets are pruned
const KEEP_SESSIONS = 30; // recent-sessions cap
const TOP_GAMES = 12;

export function emptyHistory() {
  return { v: 1, days: {}, games: {}, sessions: [] };
}

function dayKey(ms) {
  return new Date(ms).toISOString().slice(0, 10);
}

function pruneDays(h) {
  const cutoff = dayKey(Date.now() - KEEP_DAYS * DAY_MS);
  for (const k of Object.keys(h.days)) {
    if (k < cutoff) delete h.days[k];
  }
}

/**
 * Credit minutes/xp to a day + game bucket. Called once per awarded chunk
 * (extension) or once per finished session (launcher) — either way the minute
 * totals are added exactly once here.
 */
export function recordChunk(h, { placeId, minutes, xp, when }) {
  if (!h.days) h.days = {};
  if (!h.games) h.games = {};
  const ts = when || Date.now();
  const k = dayKey(ts);
  const d = h.days[k] || { minutes: 0, xp: 0 };
  d.minutes += minutes;
  d.xp += xp;
  h.days[k] = d;
  if (placeId != null) {
    const pid = String(placeId);
    const g = h.games[pid] || { minutes: 0, xp: 0, sessions: 0, lastPlayed: null };
    g.minutes += minutes;
    g.xp += xp;
    g.lastPlayed = ts;
    h.games[pid] = g;
  }
  pruneDays(h);
  return h;
}

/**
 * Append a finished session to the recent list and bump that game's session
 * count. Does NOT add minutes/xp (recordChunk already did) — only metadata.
 */
export function recordSessionMeta(h, sess) {
  if (!h.sessions) h.sessions = [];
  h.sessions.unshift({
    sessionId: sess.sessionId,
    placeId: sess.placeId != null ? Number(sess.placeId) : null,
    gameName: sess.gameName || null,
    minutes: Math.round(sess.minutes || 0),
    xp: Math.round(sess.xp || 0),
    start: sess.start || null,
    end: sess.end || null,
  });
  h.sessions = h.sessions.slice(0, KEEP_SESSIONS);
  if (sess.placeId != null) {
    if (!h.games) h.games = {};
    const pid = String(sess.placeId);
    const g = h.games[pid] || { minutes: 0, xp: 0, sessions: 0, lastPlayed: null };
    g.sessions = (g.sessions || 0) + 1;
    h.games[pid] = g;
  }
  return h;
}

/** Project raw history into the dashboard payload (merged onto server totals). */
export function buildDashboard(h) {
  const days = (h && h.days) || {};
  const games = (h && h.games) || {};
  const sessions = (h && h.sessions) || [];

  const heatmap = Object.keys(days)
    .sort()
    .map((day) => ({ day, minutes: days[day].minutes || 0, xp: days[day].xp || 0 }));

  const week = [];
  let weekMinutes = 0;
  let weekXp = 0;
  for (let i = 6; i >= 0; i--) {
    const key = dayKey(Date.now() - i * DAY_MS);
    const d = days[key] || { minutes: 0, xp: 0 };
    week.push({ day: key, minutes: d.minutes || 0, xp: d.xp || 0 });
    weekMinutes += d.minutes || 0;
    weekXp += d.xp || 0;
  }

  const todayKey = dayKey(Date.now());
  const today = { minutes: (days[todayKey] && days[todayKey].minutes) || 0 };

  const topGames = Object.keys(games)
    .map((pid) => ({
      placeId: Number(pid),
      minutes: games[pid].minutes || 0,
      xp: games[pid].xp || 0,
      sessions: games[pid].sessions || 0,
      lastPlayed: games[pid].lastPlayed || null,
    }))
    .sort((a, b) => b.minutes - a.minutes)
    .slice(0, TOP_GAMES);

  const recentSessions = sessions.slice(0, 20).map((s) => ({
    sessionId: s.sessionId,
    placeId: s.placeId,
    minutes: s.minutes || 0,
    xp: s.xp || 0,
    start: s.start,
    end: s.end,
  }));

  return {
    today,
    week,
    weekTotals: { minutes: weekMinutes, xp: weekXp },
    heatmap,
    topGames,
    recentSessions,
  };
}
