import { parseRetryAfterMs } from "../retryAfter.js";

// Constants for API endpoints
const API_ENDPOINTS = {
  USERS: "https://users.roblox.com/v1",
  FRIENDS: "https://friends.roblox.com/v1",
  PRESENCE: "https://presence.roblox.com/v1",
  GAMES: "https://games.roblox.com/v1",
  THUMBNAILS: "https://thumbnails.roblox.com/v1",
  ECONOMY: "https://economy.roblox.com/v1",
  INVENTORY: "https://inventory.roblox.com/v1",
};

// API request handler with error handling and rate limiting
class RobloxAPI {
  constructor() {
    this.rateLimitQueue = new Map();
  }

  /**
   * GET for friends/find with bounded 429 handling. Returns JSON or null if rate limited after maxAttempts.
   */
  async fetchFriendsFindPage(url, maxAttempts = 3) {
    const fetchOptions = {
      credentials: "include",
      headers: { "Content-Type": "application/json" },
    };

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      const response = await fetch(url, fetchOptions);

      if (response.status === 429) {
        const waitMs = parseRetryAfterMs(response, 5000);
        console.warn(
          `[RobloxAPI] friends/find rate limited (${attempt}/${maxAttempts}). Waiting ${waitMs}ms`
        );
        if (attempt === maxAttempts) {
          return null;
        }
        await new Promise((resolve) => setTimeout(resolve, waitMs));
        continue;
      }

      if (response.status === 401) {
        throw new Error("Unauthorized - User not authenticated");
      }

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    }

    return null;
  }

  async fetch(url, options = {}) {
    try {
      const response = await fetch(url, {
        ...options,
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
          ...options.headers,
        },
      });

      // Handle rate limiting
      if (response.status === 429) {
        const waitMs = parseRetryAfterMs(response, 5000);
        console.warn(`Rate limited. Retrying after ${waitMs}ms`);
        await new Promise((resolve) => setTimeout(resolve, waitMs));
        return this.fetch(url, options);
      }

      // Handle authentication errors
      if (response.status === 401) {
        throw new Error("Unauthorized - User not authenticated");
      }

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error("API request failed:", error);
      throw error;
    }
  }

  // Users API
  async getUserInfo(userId) {
    return this.fetch(`${API_ENDPOINTS.USERS}/users/${userId}`);
  }

  async getCurrentUser() {
    return this.fetch(`${API_ENDPOINTS.USERS}/users/authenticated`);
  }

  async searchUsers(keyword, limit = 10) {
    return this.fetch(
      `${API_ENDPOINTS.USERS}/users/search?keyword=${keyword}&limit=${limit}`
    );
  }

  // Friends API
  async getFriends(userId, limit = 50, cursor = null) {
    let url = `${API_ENDPOINTS.FRIENDS}/users/${userId}/friends/find`;
    if (cursor) url += `?cursor=${cursor}`;
    if (limit) url += `${cursor ? "&" : "?"}limit=${limit}`;
    return this.fetch(url);
  }

  /**
   * Get all friends via /v1/users/{userId}/friends/find (paginated with NextCursor).
   * @param {string|number} userId - The user ID
   * @param {number} _userSort - Legacy parameter (ignored; kept for call-site compatibility)
   * @returns {Promise<Array<{ id: number }>>} May be partial if rate limited after 3 attempts on a page.
   */
  async getAllFriends(userId, _userSort = undefined) {
    const limit = 50;
    const allFriends = [];
    let nextCursor = null;

    while (true) {
      const params = new URLSearchParams({ limit: String(limit) });
      if (nextCursor) params.set("cursor", nextCursor);

      const url = `${API_ENDPOINTS.FRIENDS}/users/${userId}/friends/find?${params}`;
      const response = await this.fetchFriendsFindPage(url);
      if (response === null) {
        console.warn(
          "[RobloxAPI] getAllFriends: stopping after repeated rate limits; returning partial list"
        );
        return allFriends;
      }

      const pageItems = response.PageItems;
      if (!Array.isArray(pageItems)) {
        throw new Error("Invalid response format from friends API");
      }

      for (const item of pageItems) {
        if (item?.id != null && item.id !== -1) {
          allFriends.push({ id: item.id });
        }
      }

      nextCursor = response.NextCursor;
      if (!nextCursor) break;
    }

    return allFriends;
  }

  async getFriendsCount(userId) {
    return this.fetch(`${API_ENDPOINTS.FRIENDS}/users/${userId}/friends/count`);
  }

  // Presence API
  async getUsersPresence(userIds) {
    return this.fetch(`${API_ENDPOINTS.PRESENCE}/presence/users`, {
      method: "POST",
      body: JSON.stringify({ userIds }),
    });
  }

  // Thumbnails API
  async getUserThumbnail(userId, type = "AvatarHeadShot", size = "420x420") {
    return this.fetch(
      `${API_ENDPOINTS.THUMBNAILS}/users/avatar-headshot?userIds=${userId}&size=${size}&format=Png`
    );
  }

  // Batch operations
  async batchRequest(requests, batchSize = 100) {
    const results = [];
    for (let i = 0; i < requests.length; i += batchSize) {
      const batch = requests.slice(i, i + batchSize);
      const batchResults = await Promise.all(
        batch.map((req) => this.fetch(req.url, req.options))
      );
      results.push(...batchResults);
    }
    return results;
  }
}

const robloxApi = new RobloxAPI();
export default robloxApi;
