import robloxApi from "../../utils/robloxApi/main.js";
import storageManager from "../../utils/storageManager.js";

class FriendRemovedNotificationChecker {
  constructor() {
    this.userFriendsData = {}; // Store per-user friend data: { userId: { friendIds: Set(), isInitialized: boolean } }
    this.currentUserId = null;
    this.initializeNotificationListener();
  }

  /**
   * Get or create user data structure
   * @param {string} userId - User ID
   * @returns {Object} User data object
   */
  getUserData(userId) {
    if (!this.userFriendsData[userId]) {
      this.userFriendsData[userId] = {
        friendIds: new Set(),
        isInitialized: false,
      };
    }
    return this.userFriendsData[userId];
  }

  /**
   * Initialize user data with friend IDs
   * @param {string} userId - User ID
   * @param {Array<number>} friendIds - Array of friend IDs
   */
  initializeUserData(userId, friendIds) {
    const userData = this.getUserData(userId);
    userData.friendIds = new Set(friendIds);
    userData.isInitialized = true;
  }

  /**
   * Handle friends list updates from the friends service
   * @param {Object} friendsData - Current user's friends list data with friendIds array
   * @param {Object} meta - Metadata about the update (accountSwitched, currentUserId, etc.)
   */
  async handleFriendsUpdate(friendsData, meta = {}) {
    try {
      const { accountSwitched = false, currentUserId = null } = meta;

      // Handle account switching
      if (accountSwitched) {
        console.log(
          `[FRIEND REMOVED] Account switched to user: ${currentUserId}`
        );

        // Always update current user ID
        this.currentUserId = currentUserId;

        // If switching to a new user, initialize or reinitialize their data
        if (currentUserId && friendsData?.friendIds) {
          // Always reinitialize when switching accounts to prevent false notifications
          this.initializeUserData(currentUserId, friendsData.friendIds);
        }
        return;
      }

      // Update current user ID if provided
      if (currentUserId) {
        this.currentUserId = currentUserId;
      }

      // Handle logout (friendsData is null)
      if (friendsData === null) {
        console.log("[FRIEND REMOVED] User logged out, clearing current user");
        this.currentUserId = null;
        return;
      }

      // Handle normal friends list updates
      if (this.currentUserId && friendsData?.friendIds) {
        const userData = this.getUserData(this.currentUserId);

        if (!userData.isInitialized) {
          // First time initialization for this user - just store without checking
          this.initializeUserData(this.currentUserId, friendsData.friendIds);
          console.log(
            `[FRIEND REMOVED] Initialized user ${this.currentUserId} with ${friendsData.friendIds.length} friends`
          );
        } else {
          // Check for removed friends for this specific user
          await this.checkForRemovedFriends(
            this.currentUserId,
            friendsData.friendIds
          );
        }
      }
    } catch (error) {
      console.error("[FRIEND REMOVED] Error handling friends update:", error);
    }
  }

  /**
   * Check for friends that have been removed for a specific user
   * @param {string} userId - User ID to check
   * @param {Array<number>} currentFriendIds - Current list of friend IDs
   */
  async checkForRemovedFriends(userId, currentFriendIds) {
    const userData = this.getUserData(userId);
    const currentSet = new Set(currentFriendIds);
    const removedFriends = [...userData.friendIds].filter(
      (id) => !currentSet.has(id)
    );

    // Filter out invalid user IDs (like -1, 0, or non-numeric values)
    const validRemovedFriends = removedFriends.filter((id) => {
      const numId = parseInt(id);
      return numId > 0 && !isNaN(numId) && numId.toString() === id.toString();
    });

    if (validRemovedFriends.length > 0) {
      console.log(
        `[FRIEND REMOVED] User ${userId} - Detected ${validRemovedFriends.length} removed friends:`,
        validRemovedFriends
      );
      await this.notifyRemovedFriends(validRemovedFriends);
    }

    // Update the user's friend IDs for next check
    userData.friendIds = currentSet;
  }

  /**
   * Initialize notification click listener
   */
  initializeNotificationListener() {
    chrome.notifications.onClicked.addListener((notificationId) => {
      if (notificationId.startsWith("friend-removed-")) {
        // Handle single friend notification
        const userId = notificationId.replace("friend-removed-", "");
        chrome.tabs.create({
          url: `https://www.roblox.com/users/${userId}/profile`,
        });
      } else if (notificationId === "multiple-friends-removed") {
        // Handle multiple friends notification
        chrome.tabs.create({
          url: "https://www.roblox.com/users/friends",
        });
      }
      chrome.notifications.clear(notificationId);
    });
  }

  /**
   * Send notifications for removed friends
   * @param {Array<number>} removedFriendIds - Array of removed friend IDs
   */
  async notifyRemovedFriends(removedFriendIds) {
    try {
      // Check if unfriend notifications are enabled
      const unfriendNotification = await storageManager.getSettings(
        "unfriend-notification",
        true
      );
      if (!unfriendNotification) {
        console.log("[FRIEND REMOVED] Notifications disabled, skipping");
        return;
      }

      // Skip if too many friends removed (likely a bug or mass unfriend)
      if (removedFriendIds.length > 10) {
        console.log(
          "[FRIEND REMOVED] Too many friends removed, skipping notification"
        );
        return;
      }

      if (removedFriendIds.length > 5) {
        // Group notification for many removed friends
        await this.sendGroupRemovedNotification(removedFriendIds);
      } else {
        // Individual notifications for few removed friends
        await this.sendIndividualRemovedNotifications(removedFriendIds);
      }
    } catch (error) {
      console.error("[FRIEND REMOVED] Failed to send notifications:", error);
    }
  }

  /**
   * Send a group notification for multiple removed friends
   * @param {Array<number>} removedFriendIds - Array of removed friend IDs
   */
  async sendGroupRemovedNotification(removedFriendIds) {
    try {
      // Get user info for first few removed friends for summary
      const userInfoPromises = removedFriendIds
        .slice(0, 3)
        .map((id) => robloxApi.getUserInfo(id));
      const userInfos = await Promise.all(userInfoPromises);

      // Create a summary message
      const usernames = userInfos.map((info) => info.name);
      const remainingCount = removedFriendIds.length - 3;
      const summaryText =
        remainingCount > 0
          ? `${usernames.join(", ")} and ${remainingCount} others`
          : usernames.join(", ");

      const notificationOptions = {
        type: "basic",
        iconUrl: "/icons/icon48.png",
        title: "Multiple Friends Removed (BetterBLOX)",
        message: `${removedFriendIds.length} friends have removed you: ${summaryText}`,
        contextMessage: "Click to view friends page",
      };

      // Add Chrome-specific properties if supported
      if (
        chrome.runtime.getManifest().manifest_version === 3 &&
        !chrome.runtime.getManifest()?.browser_specific_settings?.gecko
      ) {
        Object.assign(notificationOptions, {
          silent: true,
          priority: 1,
        });
      }

      chrome.notifications.create(
        "multiple-friends-removed",
        notificationOptions
      );

      // Auto-dismiss after 20 seconds
      setTimeout(() => {
        chrome.notifications.clear("multiple-friends-removed");
      }, 20000);
    } catch (error) {
      console.error(
        "[FRIEND REMOVED] Failed to create group notification:",
        error
      );

      // Fallback notification without user details
      chrome.notifications.create("multiple-friends-removed", {
        type: "basic",
        iconUrl: "/icons/icon48.png",
        title: "Multiple Friends Removed",
        message: `${removedFriendIds.length} friends have removed you from their friends list.`,
        contextMessage: "Click to view friends page",
      });

      setTimeout(() => {
        chrome.notifications.clear("multiple-friends-removed");
      }, 20000);
    }
  }

  /**
   * Send individual notifications for removed friends
   * @param {Array<number>} removedFriendIds - Array of removed friend IDs
   */
  async sendIndividualRemovedNotifications(removedFriendIds) {
    for (const userId of removedFriendIds) {
      try {
        const [userInfo, avatarData] = await Promise.all([
          robloxApi.getUserInfo(userId),
          robloxApi.getUserThumbnail(userId),
        ]);

        const avatarUrl = avatarData.data?.[0]?.imageUrl || "/icons/icon48.png";
        const notificationId = `friend-removed-${userId}`;

        const notificationOptions = {
          type: "basic",
          iconUrl: avatarUrl,
          title: "Friend Removed (BetterBLOX)",
          message: `${userInfo.displayName} (@${userInfo.name}) has removed you from their friends list.`,
          contextMessage: "Click to view profile",
        };

        // Add Chrome-specific properties if supported
        if (
          chrome.runtime.getManifest().manifest_version === 3 &&
          !chrome.runtime.getManifest()?.browser_specific_settings?.gecko
        ) {
          Object.assign(notificationOptions, {
            silent: true,
            priority: 1,
          });
        }

        chrome.notifications.create(notificationId, notificationOptions);

        // Auto-dismiss after 20 seconds
        setTimeout(() => {
          chrome.notifications.clear(notificationId);
        }, 20000);
      } catch (error) {
        console.error(
          `[FRIEND REMOVED] Failed to get details for user ${userId}:`,
          error
        );

        // Fallback notification without user details
        const notificationId = `friend-removed-${userId}`;
        chrome.notifications.create(notificationId, {
          type: "basic",
          iconUrl: "/icons/icon48.png",
          title: "Friend Removed (BetterBLOX)",
          message: `A user (ID: ${userId}) has removed you from their friends list.`,
          contextMessage: "Click to view profile",
        });

        setTimeout(() => {
          chrome.notifications.clear(notificationId);
        }, 20000);
      }
    }
  }

  /**
   * Manually initialize with friend IDs for a specific user (for migration purposes)
   * @param {string} userId - User ID
   * @param {Array<number>} initialFriendIds - Initial friend IDs
   */
  async initialize(userId, initialFriendIds) {
    this.initializeUserData(userId, initialFriendIds);
    console.log(
      `[FRIEND REMOVED] Manually initialized user ${userId} with ${initialFriendIds.length} friends`
    );
  }

  /**
   * Get debug information
   * @returns {Object} Debug information
   */
  getDebugInfo() {
    return {
      currentUserId: this.currentUserId,
      userCount: Object.keys(this.userFriendsData).length,
      users: Object.keys(this.userFriendsData).map((userId) => ({
        userId,
        friendCount: this.userFriendsData[userId].friendIds.size,
        isInitialized: this.userFriendsData[userId].isInitialized,
      })),
    };
  }
}

const friendRemovedNotificationChecker = new FriendRemovedNotificationChecker();
export default friendRemovedNotificationChecker;
