import storageManager from "../../utils/storageManager.js";

class SessionNotificationChecker {
  constructor() {
    this.userSessionsData = {}; // Store per-user session data: { userId: { sessions: Map(), isInitialized: boolean } }
    this.currentUserId = null;
    this.initializeNotificationListener();
  }

  /**
   * Get or create user data structure
   * @param {string} userId - User ID
   * @returns {Object} User data object
   */
  getUserData(userId) {
    if (!this.userSessionsData[userId]) {
      this.userSessionsData[userId] = {
        sessions: new Map(), // Map of token -> session data
        isInitialized: false,
      };
    }
    return this.userSessionsData[userId];
  }

  /**
   * Initialize user data with sessions
   * @param {string} userId - User ID
   * @param {Array} sessions - Array of session objects
   */
  initializeUserData(userId, sessions) {
    const userData = this.getUserData(userId);
    userData.sessions = new Map();
    sessions.forEach((session) => {
      userData.sessions.set(session.token, session);
    });
    userData.isInitialized = true;
  }

  /**
   * Handle sessions updates from the sessions service
   * @param {Object} sessionsData - Current user's sessions data with sessions array
   * @param {Object} meta - Metadata about the update (accountSwitched, currentUserId, etc.)
   */
  async handleSessionsUpdate(sessionsData, meta = {}) {
    try {
      const { accountSwitched = false, currentUserId = null } = meta;

      // Handle account switching
      if (accountSwitched) {
        console.log(
          `[SESSION NOTIFICATION] Account switched to user: ${currentUserId}`
        );

        // Always update current user ID
        this.currentUserId = currentUserId;

        // If switching to a new user, initialize or reinitialize their data
        if (currentUserId && sessionsData?.sessions) {
          // Always reinitialize when switching accounts to prevent false notifications
          this.initializeUserData(currentUserId, sessionsData.sessions);
        }
        return;
      }

      // Update current user ID if provided
      if (currentUserId) {
        this.currentUserId = currentUserId;
      }

      // Handle logout (sessionsData is null)
      if (sessionsData === null) {
        console.log(
          "[SESSION NOTIFICATION] User logged out, clearing current user"
        );
        this.currentUserId = null;
        return;
      }

      // Handle normal sessions updates
      if (this.currentUserId && sessionsData?.sessions) {
        const userData = this.getUserData(this.currentUserId);

        if (!userData.isInitialized) {
          // First time initialization for this user - just store without checking
          this.initializeUserData(this.currentUserId, sessionsData.sessions);
          console.log(
            `[SESSION NOTIFICATION] Initialized user ${this.currentUserId} with ${sessionsData.sessions.length} sessions`
          );
        } else {
          // Check for new sessions for this specific user
          await this.checkForNewSessions(
            this.currentUserId,
            sessionsData.sessions
          );
        }
      }
    } catch (error) {
      console.error(
        "[SESSION NOTIFICATION] Error handling sessions update:",
        error
      );
    }
  }

  /**
   * Check for new sessions for a specific user
   * @param {string} userId - User ID to check
   * @param {Array} currentSessions - Current list of session objects
   */
  async checkForNewSessions(userId, currentSessions) {
    const userData = this.getUserData(userId);
    const currentSessionsMap = new Map();

    // Create map of current sessions
    currentSessions.forEach((session) => {
      currentSessionsMap.set(session.token, session);
    });

    // Find new sessions (tokens that weren't in the previous sessions)
    const newSessions = currentSessions.filter(
      (session) => !userData.sessions.has(session.token)
    );

    if (newSessions.length > 0) {
      console.log(
        `[SESSION NOTIFICATION] User ${userId} - Detected ${newSessions.length} new sessions:`,
        newSessions.map((s) => {
          const city = s.location?.city || "Unknown";
          let agentInfo = "Unknown";
          if (s.agent) {
            if (s.agent.type === "App") {
              agentInfo = s.agent.value || "Roblox App";
            } else {
              agentInfo = s.agent.value || s.agent.type || "Unknown";
            }
          }
          return `${city}, ${agentInfo}`;
        })
      );
      await this.notifyNewSessions(newSessions);
    }

    // Update the user's sessions for next check
    userData.sessions = currentSessionsMap;
  }

  /**
   * Initialize notification click listener
   */
  initializeNotificationListener() {
    chrome.notifications.onClicked.addListener((notificationId) => {
      if (
        notificationId.startsWith("new-session-") ||
        notificationId === "multiple-new-sessions"
      ) {
        // Open Roblox security page
        chrome.tabs.create({
          url: "https://www.roblox.com/my/account#!/security",
        });
      }
      chrome.notifications.clear(notificationId);
    });
  }

  /**
   * Send notifications for new sessions
   * @param {Array} newSessions - Array of new session objects
   */
  async notifyNewSessions(newSessions) {
    try {
      // Check if session notifications are enabled
      const sessionNotification = await storageManager.getSettings(
        "session-notification",
        false
      );
      if (!sessionNotification) {
        console.log("[SESSION NOTIFICATION] Notifications disabled, skipping");
        return;
      }

      // Skip if too many sessions (likely a bug)
      if (newSessions.length > 10) {
        console.log(
          "[SESSION NOTIFICATION] Too many new sessions, skipping notification"
        );
        return;
      }

      if (newSessions.length > 3) {
        // Group notification for many new sessions
        await this.sendGroupSessionNotification(newSessions);
      } else {
        // Individual notifications for few new sessions
        await this.sendIndividualSessionNotifications(newSessions);
      }
    } catch (error) {
      console.error(
        "[SESSION NOTIFICATION] Failed to send notifications:",
        error
      );
    }
  }

  /**
   * Send a group notification for multiple new sessions
   * @param {Array} newSessions - Array of new session objects
   */
  async sendGroupSessionNotification(newSessions) {
    try {
      // Create a summary of locations
      const locations = newSessions
        .map((session) => session.location?.city || "Unknown location")
        .slice(0, 3);
      const remainingCount = newSessions.length - 3;
      const summaryText =
        remainingCount > 0
          ? `${locations.join(", ")} and ${remainingCount} others`
          : locations.join(", ");

      const notificationOptions = {
        type: "basic",
        iconUrl: "/icons/icon48.png",
        title: "Multiple New Sessions",
        message: `${newSessions.length} new sessions detected from: ${summaryText}`,
        contextMessage: "Click to view security settings",
      };

      // Add Chrome-specific properties if supported
      if (
        chrome.runtime.getManifest().manifest_version === 3 &&
        !chrome.runtime.getManifest()?.browser_specific_settings?.gecko
      ) {
        Object.assign(notificationOptions, {
          silent: true,
          priority: 2, // Higher priority for security notifications
        });
      }

      chrome.notifications.create("multiple-new-sessions", notificationOptions);

      // Auto-dismiss after 30 seconds (longer for security notifications)
      setTimeout(() => {
        chrome.notifications.clear("multiple-new-sessions");
      }, 30000);
    } catch (error) {
      console.error(
        "[SESSION NOTIFICATION] Failed to create group notification:",
        error
      );

      // Fallback notification without details
      chrome.notifications.create("multiple-new-sessions", {
        type: "basic",
        iconUrl: "/icons/icon48.png",
        title: "Multiple New Sessions",
        message: `${newSessions.length} new login sessions detected on your account.`,
        contextMessage: "Click to view security settings",
      });

      setTimeout(() => {
        chrome.notifications.clear("multiple-new-sessions");
      }, 30000);
    }
  }

  /**
   * Send individual notifications for new sessions
   * @param {Array} newSessions - Array of new session objects
   */
  async sendIndividualSessionNotifications(newSessions) {
    for (let i = 0; i < newSessions.length; i++) {
      const session = newSessions[i];
      try {
        const notificationId = `new-session-${Date.now()}-${i}`;

        // Format session information
        const location = session.location
          ? `${session.location.city || "Unknown city"}, ${
              session.location.country || "Unknown country"
            }`
          : "Unknown location";

        // Handle different agent types (Browser, App, etc.)
        let device = "Unknown device";
        if (session.agent) {
          if (session.agent.type === "App") {
            // For mobile apps, agent.value might be null
            const appName = session.agent.value || "Roblox App";
            device = `${appName} on ${session.agent.os || "Unknown OS"}`;
          } else if (session.agent.type === "Browser") {
            device = `${session.agent.value || "Unknown browser"} on ${
              session.agent.os || "Unknown OS"
            }`;
          } else {
            // Handle other types
            const agentName =
              session.agent.value || session.agent.type || "Unknown";
            device = `${agentName} on ${session.agent.os || "Unknown OS"}`;
          }
        }

        const timestamp = session.lastAccessedTimestampEpochMilliseconds
          ? new Date(
              parseInt(session.lastAccessedTimestampEpochMilliseconds)
            ).toLocaleString()
          : "Unknown time";

        const notificationOptions = {
          type: "basic",
          iconUrl: "/icons/icon48.png",
          title: "New Login Session",
          message: `New login detected from ${location} using ${device}`,
          contextMessage: `${timestamp} - Click to view security settings`,
        };

        // Add Chrome-specific properties if supported
        if (
          chrome.runtime.getManifest().manifest_version === 3 &&
          !chrome.runtime.getManifest()?.browser_specific_settings?.gecko
        ) {
          Object.assign(notificationOptions, {
            silent: true,
            priority: 2, // Higher priority for security notifications
          });
        }

        chrome.notifications.create(notificationId, notificationOptions);

        // Auto-dismiss after 30 seconds (longer for security notifications)
        setTimeout(() => {
          chrome.notifications.clear(notificationId);
        }, 30000);
      } catch (error) {
        console.error(
          `[SESSION NOTIFICATION] Failed to create notification for session:`,
          error
        );

        // Fallback notification without details
        const notificationId = `new-session-${Date.now()}-${i}`;
        chrome.notifications.create(notificationId, {
          type: "basic",
          iconUrl: "/icons/icon48.png",
          title: "New Login Session",
          message: "A new login session was detected on your account.",
          contextMessage: "Click to view security settings",
        });

        setTimeout(() => {
          chrome.notifications.clear(notificationId);
        }, 30000);
      }
    }
  }

  /**
   * Manually initialize with sessions for a specific user (for migration purposes)
   * @param {string} userId - User ID
   * @param {Array} initialSessions - Initial sessions
   */
  async initialize(userId, initialSessions) {
    this.initializeUserData(userId, initialSessions);
    console.log(
      `[SESSION NOTIFICATION] Manually initialized user ${userId} with ${initialSessions.length} sessions`
    );
  }

  /**
   * Get debug information
   * @returns {Object} Debug information
   */
  getDebugInfo() {
    return {
      currentUserId: this.currentUserId,
      userCount: Object.keys(this.userSessionsData).length,
      users: Object.keys(this.userSessionsData).map((userId) => ({
        userId,
        sessionCount: this.userSessionsData[userId].sessions.size,
        isInitialized: this.userSessionsData[userId].isInitialized,
      })),
    };
  }
}

const sessionNotificationChecker = new SessionNotificationChecker();
export default sessionNotificationChecker;
