import storageManager from "../../utils/storageManager.js";
import authManager from "../authentication/getAuthStatus.js";
import { FAST_API_BASE_URL } from "../../constants.js";

const SERVER_DISCOVERY_CHECK_INTERVAL = 5 * 60 * 1000; // 5 minutes - optimized
const SERVER_API_URL = `${FAST_API_BASE_URL}/api/discovery`;
const GAMEJOIN_API_URL = "https://gamejoin.roblox.com/v1/join-game-instance";

// chrome.alarms survives MV3 service-worker unloads; setTimeout does not.
const SERVER_DISCOVERY_ALARM_NAME = "serverScanCheck";

class ServerScanService {
  constructor() {
    this.isRunning = false;
    this.currentTask = null;
    this.extensionId = null;
    this.wasAuthenticated = false;
    this.isRequestInProgress = false; // Prevent overlapping requests
    this.alarmListener = null;
  }

  async initialize() {
    // console.log("[SERVER DISCOVERY] Initializing server discovery service...");
    this.startServerDiscoveryScheduler();
  }

  /**
   * Get or update the extension ID based on authenticated user
   */
  async updateExtensionId() {
    try {
      const authData = await authManager.getAuthData();
      if (authData && authData.id) {
        this.extensionId = `user-${authData.id}`;
        // console.log(
        //   `[SERVER DISCOVERY] Using player ID as extension identifier: ${this.extensionId}`
        // );
        return true;
      } else {
        // console.log("[SERVER DISCOVERY] No authenticated user found");
        this.extensionId = null;
        return false;
      }
    } catch (error) {
      // console.error("[SERVER DISCOVERY] Error getting auth data:", error);
      this.extensionId = null;
      return false;
    }
  }

  /**
   * Start the scheduler to periodically check for server discovery tasks
   */
  startServerDiscoveryScheduler() {
    if (this.isRunning) {
      return; // Already running
    }

    this.isRunning = true;
    // console.log(
    //   "[SERVER DISCOVERY] Starting server discovery task scheduler (5-minute intervals)"
    // );

    // Periodic alarm survives service-worker suspension (unlike setTimeout).
    chrome.alarms.create(SERVER_DISCOVERY_ALARM_NAME, {
      periodInMinutes: SERVER_DISCOVERY_CHECK_INTERVAL / 60000,
    });

    if (!this.alarmListener) {
      this.alarmListener = (alarm) => {
        if (alarm.name === SERVER_DISCOVERY_ALARM_NAME) {
          this.checkForServerTask();
        }
      };
      chrome.alarms.onAlarm.addListener(this.alarmListener);
    }

    // Kick off the first run shortly after start (the alarm's first fire can
    // be several minutes away).
    setTimeout(() => this.checkForServerTask(), 1000);
  }

  /**
   * Stop the scheduler
   */
  stopServerDiscoveryScheduler() {
    chrome.alarms.clear(SERVER_DISCOVERY_ALARM_NAME);
    if (this.alarmListener) {
      chrome.alarms.onAlarm.removeListener(this.alarmListener);
      this.alarmListener = null;
    }
    this.isRunning = false;
    // console.log("[SERVER DISCOVERY] Server discovery task scheduler stopped");
  }

  /**
   * Check for server discovery tasks - OPTIMIZED
   */
  async checkForServerTask() {
    if (!this.isRunning || this.currentTask || this.isRequestInProgress) {
      return;
    }

    this.isRequestInProgress = true;

    try {
      // Quick auth and ID checks
      if (!(await authManager.isAuthenticated())) {
        this.wasAuthenticated = false;
        this.scheduleNextCheck();
        return;
      }

      if (!this.extensionId && !(await this.updateExtensionId())) {
        this.scheduleNextCheck();
        return;
      }

      this.wasAuthenticated = true;

      // Get server task
      const response = await fetch(`${SERVER_API_URL}/get-server-task`, {
        method: "GET",
        headers: { "X-Extension-Id": this.extensionId },
      });

      if (!response.ok) {
        this.scheduleNextCheck();
        return;
      }

      const result = await response.json();
      if (!result.success || !result.hasTask) {
        this.scheduleNextCheck();
        return;
      }

      // Process server task
      this.currentTask = result.task;
      console.log(
        `[SERVER DISCOVERY] Processing ${this.currentTask.totalServers} servers`
      );

      await this.processServerTask(this.currentTask);
      this.scheduleNextCheck();
    } catch (error) {
      console.error("[SERVER DISCOVERY] Error in server task check:", error);
      this.scheduleNextCheck();
    } finally {
      this.isRequestInProgress = false;
    }
  }

  /**
   * Process a server discovery task - OPTIMIZED
   */
  async processServerTask(task) {
    try {
      const serverResults = [];
      const BATCH_SIZE = 8; // Reduced batch size for better performance
      const BATCH_DELAY = 300; // Reduced delay

      // Process servers in smaller batches
      for (let i = 0; i < task.servers.length; i += BATCH_SIZE) {
        const batch = task.servers.slice(i, i + BATCH_SIZE);

        const batchResults = await Promise.allSettled(
          batch.map(async (server) => {
            try {
              const joinResponse = await fetch(GAMEJOIN_API_URL, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  placeId: server.placeId,
                  gameId: server.serverId,
                }),
              });

              if (!joinResponse.ok) {
                return {
                  id: null,
                  serverId: server.serverId,
                  placeId: server.placeId,
                  status: joinResponse.status,
                  version: null,
                };
              }

              const joinData = await joinResponse.json();
              const serverUpdateData = {
                serverId: server.serverId,
                status: joinData.status,
                placeId: server.placeId,
                version: joinData.PlaceVersion,
              };
              const { joinScript } = joinData;
              if (!joinScript) return serverUpdateData;

              // Extract datacenter info for successful joins
              if (joinScript?.DataCenterId) {
                const connection = joinScript.UdmuxEndpoints?.[0] || null;

                serverUpdateData.datacenter = {
                  id: joinScript.DataCenterId,
                  ip: connection ? connection.Address : null,
                };
              }

              return serverUpdateData;
            } catch (error) {
              return {
                id: null,
                serverId: server.serverId,
                placeId: server.placeId,
                status: -1,
                version: null,
              }; // Network error
            }
          })
        );

        // Collect results
        for (const result of batchResults) {
          if (result.status === "fulfilled" && result.value) {
            serverResults.push(result.value);
          }
        }

        // Brief delay between batches
        if (i + BATCH_SIZE < task.servers.length) {
          await new Promise((resolve) => setTimeout(resolve, BATCH_DELAY));
        }
      }

      // Submit results
      if (serverResults.length > 0) {
        await this.submitServerTask({ servers: serverResults });
      }

      console.log(
        `[SERVER DISCOVERY] Processed ${serverResults.length}/${task.totalServers} servers`
      );

      this.currentTask = null;
    } catch (error) {
      console.error("[SERVER DISCOVERY] Error processing server batch:", error);
      this.currentTask = null;
    }
  }

  /**
   * Submit server task results - OPTIMIZED
   */
  async submitServerTask(taskResult) {
    try {
      const response = await fetch(`${SERVER_API_URL}/submit-server-task`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Extension-Id": this.extensionId,
        },
        body: JSON.stringify(taskResult),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit server task: ${response.statusText}`);
      }

      const result = await response.json();
      if (!result.success) {
        console.error(
          "[SERVER DISCOVERY] Server rejected submission:",
          result.error
        );
      }
    } catch (error) {
      console.error("[SERVER DISCOVERY] Error submitting server task:", error);
      throw error;
    }
  }

  /**
   * Schedule the next server task check - OPTIMIZED
   */
  scheduleNextCheck() {
    // No-op: the recurring chrome.alarm drives the cadence. Retained so the
    // existing call sites stay valid (and as a hook for future backoff).
  }
}

// Create singleton instance
const serverScanService = new ServerScanService();

export default serverScanService;
