import getAuthStatus from "../authentication/getAuthStatus.js";
import storageManager from "../../utils/storageManager.js";
import { notifyRobloxTabs } from "../../utils/notifyRobloxTabs.js";

const SESSIONS_STORAGE_KEY = "sessions_data"; // Will be used with storageManager prefix
// NOTE: chrome.alarms clamps periodInMinutes to a 1-minute floor for packed
// (production) extensions (30s for unpacked dev builds). Any sub-minute value
// here is silently raised to ~1 min in production, so we use the 1-minute
// minimum rather than implying a faster cadence the platform won't honor.
const SESSIONS_CHECK_INTERVAL_MINUTES = 1; // clamped to Chrome's alarm floor

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

class SessionsService {
  constructor() {
    this.sessionsData = {}; // Will store per-user session data: { userId: { sessions: [], lastUpdated: "" } }
    this.currentUserId = null;
    this.subscribers = [];
    this.isInitialized = false;
  }

  /**
   * Add a subscriber to receive session updates
   * @param {Object} subscriber - Object with handleSessionsUpdate method
   * @returns {boolean} - Success status
   */
  addSubscriber(subscriber) {
    if (typeof subscriber.handleSessionsUpdate === "function") {
      console.log("[SESSIONS] Adding subscriber", subscriber.constructor.name);
      this.subscribers.push(subscriber);
      return true;
    }
    console.warn(
      "[SESSIONS] Attempted to add invalid subscriber - missing handleSessionsUpdate method"
    );
    return false;
  }

  /**
   * Remove a subscriber from session updates
   * @param {Object} subscriber - Subscriber to remove
   * @returns {boolean} - Success status
   */
  removeSubscriber(subscriber) {
    const index = this.subscribers.indexOf(subscriber);
    if (index > -1) {
      this.subscribers.splice(index, 1);
      console.log("[SESSIONS] Removed subscriber", subscriber.constructor.name);
      return true;
    }
    return false;
  }

  /**
   * Initialize the sessions service
   */
  async initialize() {
    if (this.isInitialized) {
      console.log("[SESSIONS] Service already initialized");
      return;
    }

    console.log("[SESSIONS] Initializing sessions service");

    try {
      // Load all sessions data from storage using storageManager
      this.sessionsData = await storageManager.get(SESSIONS_STORAGE_KEY, {});

      // Get current user ID if available
      await this.updateCurrentUser();

      console.log(
        `[SESSIONS] Loaded sessions data for ${
          Object.keys(this.sessionsData).length
        } users`
      );
      if (this.currentUserId) {
        const currentUserSessions = this.sessionsData[this.currentUserId];
        console.log(
          `[SESSIONS] Current user ${this.currentUserId} has ${
            currentUserSessions?.sessions?.length || 0
          } sessions`
        );
      }

      this.isInitialized = true;
      await this.startPeriodicCheck();
    } catch (error) {
      console.error("[SESSIONS] Failed to initialize:", error);
    }
  }

  /**
   * Update current user ID and handle account switching
   */
  async updateCurrentUser() {
    try {
      const authData = await getAuthStatus.getAuthData(true);
      const newUserId = authData?.id?.toString();

      if (newUserId !== this.currentUserId) {
        const previousUserId = this.currentUserId;
        this.currentUserId = newUserId;

        if (previousUserId && newUserId) {
          console.log(
            `[SESSIONS] Account switched from ${previousUserId} to ${newUserId}`
          );
          await this.notifySessionsChanged(true); // true = account switched
        } else if (newUserId) {
          console.log(`[SESSIONS] User logged in: ${newUserId}`);
          await this.notifySessionsChanged(true); // true = account switched
        }
      }

      return newUserId;
    } catch (error) {
      console.error("[SESSIONS] Failed to update current user:", error);
      return null;
    }
  }

  /**
   * Update the sessions list from Roblox API
   */
  async updateSessionsList() {
    try {
      // Always get fresh user ID directly from API, don't rely on cached data
      const freshUserId = (
        await getAuthStatus.getAuthData(true)
      )?.id?.toString();

      if (!freshUserId) {
        console.log(
          "[SESSIONS] User not authenticated, skipping sessions update"
        );
        return;
      }

      // Check if user switched accounts
      if (freshUserId !== this.currentUserId) {
        const previousUserId = this.currentUserId;
        this.currentUserId = freshUserId;

        if (previousUserId && freshUserId) {
          console.log(
            `[SESSIONS] Account switched from ${previousUserId} to ${freshUserId}`
          );
          await this.notifySessionsChanged(true); // true = account switched
        } else if (freshUserId) {
          console.log(`[SESSIONS] User logged in: ${freshUserId}`);
          await this.notifySessionsChanged(true); // true = account switched
        }
      }

      const userId = freshUserId;

      console.log(`[SESSIONS] Fetching sessions for user: ${userId}`);
      const sessions = await this.fetchUserSessions();

      // Get previous sessions for this user (not global)
      const previousUserData = this.sessionsData[userId];
      const previousSessions = previousUserData?.sessions || [];

      // Update sessions data for this specific user
      this.sessionsData[userId] = {
        lastUpdated: new Date().toISOString(),
        sessions: sessions,
        count: sessions.length,
      };

      // Save to storage and notify subscribers
      await this.notifySessionsChanged();

      console.log(
        `[SESSIONS] Updated sessions list for user ${userId}: ${sessions.length} sessions found`
      );

      // Log changes if any (only for debugging)
      const added = sessions.filter(
        (s) => !previousSessions.some((ps) => ps.token === s.token)
      );
      const removed = previousSessions.filter(
        (ps) => !sessions.some((s) => s.token === ps.token)
      );

      if (added.length > 0) {
        console.log(`[SESSIONS] New sessions detected: ${added.length}`);
      }
      if (removed.length > 0) {
        console.log(`[SESSIONS] Sessions removed: ${removed.length}`);
      }
    } catch (error) {
      console.error("[SESSIONS] Failed to update sessions list:", error);
    }
  }

  /**
   * Fetch user sessions from Roblox API
   */
  async fetchUserSessions() {
    try {
      const response = await fetch(
        "https://apis.roblox.com/token-metadata-service/v1/sessions?nextCursor=&desiredLimit=100",
        {
          credentials: "include",
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      return data.sessions || [];
    } catch (error) {
      console.error("[SESSIONS] Failed to fetch sessions:", error);
      return [];
    }
  }

  /**
   * Notify all subscribers and update storage when sessions change
   * @param {boolean} accountSwitched - Whether this notification is due to account switching
   */
  async notifySessionsChanged(accountSwitched = false) {
    try {
      // Save all sessions data to storage using storageManager
      await storageManager.set(SESSIONS_STORAGE_KEY, this.sessionsData);

      // Get current user's sessions data for notifications
      const currentUserSessions = this.getCurrentUserSessions();

      // Notify direct subscribers
      if (this.subscribers.length > 0) {
        console.log(
          `[SESSIONS] Notifying ${this.subscribers.length} direct subscribers`
        );
        for (const subscriber of this.subscribers) {
          try {
            await subscriber.handleSessionsUpdate(currentUserSessions, {
              accountSwitched,
              currentUserId: this.currentUserId,
              allUsersData: this.sessionsData,
            });
          } catch (error) {
            console.error("[SESSIONS] Error notifying subscriber:", error);
          }
        }
      }

      // Notify content scripts in Roblox tabs
      await notifyRobloxTabs("SESSIONS_UPDATED", currentUserSessions, {
        accountSwitched,
        currentUserId: this.currentUserId,
      });
    } catch (error) {
      console.error("[SESSIONS] Failed to notify sessions changed:", error);
    }
  }

  /**
   * Start periodic sessions checking
   */
  async startPeriodicCheck() {
    // Initial update
    await this.updateSessionsList();

    // Set up periodic alarm (Chrome enforces a 1-minute minimum period in
    // production, so this fires roughly once per minute regardless of intent)
    chrome.alarms.create("sessionsCheck", {
      periodInMinutes: SESSIONS_CHECK_INTERVAL_MINUTES,
    });

    // Listen for alarm
    chrome.alarms.onAlarm.addListener((alarm) => {
      if (alarm.name === "sessionsCheck") {
        this.updateSessionsList();
      }
    });

    // Retry until the current user has sessions data, but unawaited and
    // bounded: awaiting this loop blocked the whole background init chain
    // (and with it every message handler) for as long as the sessions API
    // kept failing.
    void (async () => {
      const MAX_RETRIES = 30;
      for (
        let attempt = 0;
        attempt < MAX_RETRIES && this.currentUserId && !this.getCurrentUserSessions();
        attempt++
      ) {
        console.log(
          "[SESSIONS] No sessions data found for current user, waiting 10 seconds before retrying"
        );
        await delay(10000);
        await this.updateSessionsList();
      }
    })();
  }

  /**
   * Get current user's sessions data
   * @returns {Object|null} Current user's sessions data object
   */
  getCurrentUserSessions() {
    if (!this.currentUserId) {
      return null;
    }
    return this.sessionsData[this.currentUserId] || null;
  }

  /**
   * Get sessions data for a specific user
   * @param {string} userId - User ID to get sessions for
   * @returns {Object|null} Sessions data for the specified user
   */
  getUserSessions(userId) {
    return this.sessionsData[userId] || null;
  }

  /**
   * Get current sessions list (legacy compatibility)
   * @returns {Object|null} Current user's sessions list object
   */
  getSessionsList() {
    return this.getCurrentUserSessions();
  }

  /**
   * Get sessions array for current user
   * @returns {Array} Array of session objects
   */
  async getSessions() {
    const currentUserSessions = this.getCurrentUserSessions();
    if (currentUserSessions?.sessions) {
      return currentUserSessions.sessions;
    }

    // Fallback to storage if not in memory
    if (this.currentUserId) {
      const stored = await storageManager.get(SESSIONS_STORAGE_KEY, {});
      return stored[this.currentUserId]?.sessions || [];
    }

    return [];
  }

  /**
   * Get sessions for a specific user
   * @param {string} userId - User ID to get sessions for
   * @returns {Array} Array of session objects
   */
  async getSessionsForUser(userId) {
    const userSessions = this.getUserSessions(userId);
    if (userSessions?.sessions) {
      return userSessions.sessions;
    }

    // Fallback to storage
    const stored = await storageManager.get(SESSIONS_STORAGE_KEY, {});
    return stored[userId]?.sessions || [];
  }

  /**
   * Get sessions count for current user
   * @returns {number} Number of sessions
   */
  async getSessionsCount() {
    const sessions = await this.getSessions();
    return sessions.length;
  }

  /**
   * Get all users data (for debugging/admin purposes)
   * @returns {Object} All users sessions data
   */
  getAllUsersData() {
    return this.sessionsData;
  }

  /**
   * Get current user ID
   * @returns {string|null} Current user ID
   */
  getCurrentUserId() {
    return this.currentUserId;
  }
}

// Create and export the service instance
const sessionsService = new SessionsService();
export default sessionsService;
