import storageManager from "../../utils/storageManager.js";

class OnlineNotificationChecker {
  constructor() {
    this.previousPresenceData = new Map();
    this.initializeNotificationListener();
  }

  async handlePresenceUpdate(presenceData) {
    try {
      // Get list of users to notify about
      const notifyList = await storageManager.get("notifyOnline", []);
      if (!notifyList || !Array.isArray(notifyList) || !notifyList.length) return;

      for (const [userId, presence] of Object.entries(presenceData)) {
        // Skip if user is not in notify list
        if (!notifyList.includes(userId)) continue;

        const wasOnline =
          this.previousPresenceData.get(userId)?.userPresenceType > 0;
        const isOnline = presence.userPresenceType > 0;

        // Notify if user just came online
        if (!wasOnline && isOnline) {
          await this.sendOnlineNotification(userId, presence);
        }

        // Update previous presence data
        this.previousPresenceData.set(userId, presence);
      }
    } catch (error) {
      console.error("Error checking online status:", error);
    }
  }

  initializeNotificationListener() {
    chrome.notifications.onClicked.addListener((notificationId) => {
      if (notificationId.startsWith("friend-online-")) {
        const userId = notificationId.replace("friend-online-", "");
        chrome.tabs.create({
          url: `https://www.roblox.com/users/${userId}/profile`,
        });
      }
      chrome.notifications.clear(notificationId);
    });
  }

  async sendOnlineNotification(userId, presence) {
    try {
      const [userInfo, avatarData] = await Promise.all([
        getUserInfo(userId),
        getUserThumbnail(userId),
      ]);

      const avatarUrl = avatarData.data?.[0]?.imageUrl || "/icons/icon48.png";
      let message = `${userInfo.displayName} (@${userInfo.name}) is now online`;

      // Add game info if they're in a game
      if (presence.userPresenceType === 2 && presence.lastLocation) {
        message += `\nPlaying: ${presence.lastLocation}`;
      }
      // Create browser-compatible notification options
      const notificationOptions = {
        type: "basic",
        iconUrl: avatarUrl,
        title: "Friend Online",
        message: message,
        contextMessage: "Click to view profile",
      };

      // Add Chrome-specific properties if supported
      if (
        chrome.runtime.getManifest().manifest_version === 3 &&
        !chrome.runtime.getManifest()?.browser_specific_settings?.gecko
      ) {
        Object.assign(notificationOptions, {
          silent: true,
          priority: 2,
        });
      }

      chrome.notifications.create(
        `friend-online-${userId}`,
        notificationOptions
      );

      // Auto-dismiss after 10 seconds
      setTimeout(() => {
        chrome.notifications.clear(`friend-online-${userId}`);
      }, 10000);
    } catch (error) {
      console.error(`Failed to create notification for user ${userId}:`, error);
    }
  }
}

async function getUserInfo(userId) {
  if (!userId) {
    console.log("[ONLINE NOTIFICATION] No user id provided");
    return null;
  }

  const response = await fetch(`https://users.roblox.com/v1/users/${userId}`, {
    method: "GET",
  });

  if (!response.ok) {
    console.error(
      "[ONLINE NOTIFICATION] Failed to fetch user info:",
      response.statusText
    );
    return null;
  }

  const data = await response.json();
  return data;
}

async function getUserThumbnail(
  userId,
  type = "AvatarHeadShot",
  size = "420x420"
) {
  if (!userId) {
    console.log("[ONLINE NOTIFICATION] No user id provided");
    return null;
  }

  const response = await fetch(
    `https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=${userId}&size=${size}&format=Png`,
    {
      method: "GET",
    }
  );

  if (!response.ok) {
    console.error(
      "[ONLINE NOTIFICATION] Failed to fetch user info:",
      response.statusText
    );
    return null;
  }

  const data = await response.json();
  return data;
}

const onlineNotificationChecker = new OnlineNotificationChecker();
export default onlineNotificationChecker;
