// Store CSRF token across calls so a refresh from one response carries to the next
let csrfToken = null;

/** Convert a `Headers` object into a plain JSON-serializable object. */
function serializeHeaders(headers) {
  const out = {};
  headers.forEach((value, name) => {
    out[name] = value;
  });
  return out;
}

/** Try JSON first, fall back to text. Match prior behavior on parse failure. */
async function parseResponseBody(response) {
  try {
    return await response.json();
  } catch {
    return await response.text();
  }
}

/**
 * Handles API requests proxied from content scripts / popup via the service worker.
 *
 * Behavior preserved from the previous implementation:
 *   - GET-style CSRF token capture from `x-csrf-token` response header
 *   - On 403 with an existing token, retry exactly once with the stored token
 *   - Return shape: `{ data, status, headers }` on success,
 *     `{ error, message?, status?, headers? }` on error, `{ error }` on fetch fail
 *
 * @param {Object} payload
 * @param {string} payload.url
 * @param {RequestInit} payload.options
 * @param {{ mode?: 'text' | 'json' }} [payload.payloadOptions]
 */
export async function handleApiRequest(payload) {
  const { url, options, payloadOptions } = payload;
  try {
    const requestOptions = { ...options };
    if (!requestOptions.headers) {
      requestOptions.headers = {};
    }
    if (csrfToken) {
      requestOptions.headers["x-csrf-token"] = csrfToken;
    }

    const response = await fetch(url, requestOptions);

    if (response.headers.has("x-csrf-token")) {
      csrfToken = response.headers.get("x-csrf-token");
    }

    if (!response.ok) {
      // 403 + token => single retry with the refreshed token
      if (response.status === 403 && csrfToken) {
        requestOptions.headers["x-csrf-token"] = csrfToken;
        return await retryWithCsrf(url, requestOptions);
      }

      const errorMessage = await parseResponseBody(response);
      return {
        error: `API request failed with status ${response.status}`,
        message: errorMessage,
        status: response.status,
        headers: serializeHeaders(response.headers),
      };
    }

    const data =
      payloadOptions?.mode === "text"
        ? await response.text()
        : await response.json();

    return {
      data,
      status: response.status,
      headers: serializeHeaders(response.headers),
    };
  } catch (error) {
    return {
      error: `Fetch error: ${error.message}`,
    };
  }
}

/** One-shot retry after a 403. Caller has already set `x-csrf-token` on requestOptions. */
async function retryWithCsrf(url, requestOptions) {
  try {
    console.log("Retrying request with CSRF token");
    const retryResponse = await fetch(url, requestOptions);
    const headers = serializeHeaders(retryResponse.headers);

    if (retryResponse.ok) {
      const data = await retryResponse.json();
      return { data, status: retryResponse.status, headers };
    }

    const errorText = await retryResponse.text();
    return {
      error: `API request failed after CSRF retry with status ${retryResponse.status}: ${errorText}`,
      status: retryResponse.status,
      headers,
    };
  } catch (retryError) {
    return {
      error: `CSRF retry error: ${retryError.message}`,
      status: 500,
    };
  }
}
