/**
 * Resolved once service initialization finishes (successfully or not).
 * Message handlers await this so a message arriving mid-init (or one that
 * woke a terminated service worker) is answered instead of dropped.
 */
let resolveServicesReady;
const servicesReady = new Promise((resolve) => {
  resolveServicesReady = resolve;
});

export async function initBackgroundScriptV2() {
  console.log("[BETTERBLOX] Initializing v2 background theme bridge");
  try {
    authManager.init();
    extensionUpdater.init();
    getServerIP.init();

    // Connect presence service subscribers
    presenceService.addSubscriber(presenceTracker);
    presenceService.addSubscriber(onlineNotification);
    presenceService.addSubscriber(playNotification);
    presenceService.addSubscriber(optimizedServerSync); // Add optimized server sync
    presenceService.addSubscriber(playtimeXpService); // Award playtime XP for own in-game time

    // Connect friends service subscribers
    friendsService.addSubscriber(friendRemovedNotification);

    // Connect sessions service subscribers
    sessionsService.addSubscriber(sessionNotification);

    // Initialize services
    await friendsService.initialize();
    await sessionsService.initialize();
    await presenceService.initialize();
    await optimizedServerSync.initialize(); // Initialize optimized server sync
    await markActiveUser.initialize(); // Initialize user activity tracking
    await playtimeXpService.init(); // Eager init for consistency (was only lazy-initialized)
    await gameDiscoveryService.initialize();
    await serverScanService.initialize();
  } finally {
    // Unblock queued messages even when an init step throws — a broken
    // service should degrade its own handlers, not silence every handler.
    resolveServicesReady();
  }
}

/**
 * Wrap an async function as a runtime.onMessage handler.
 * Handler always returns true (keeps the message channel open for async sendResponse).
 *
 * @param {(message: any) => Promise<any>} produce - returns the response payload
 * @param {object} [opts]
 * @param {string} [opts.logPrefix] - prefix for console.error on failure
 * @param {(error: Error) => any} [opts.onError] - shape error response (default: `{error: message}`)
 */
function makeAsyncHandler(produce, opts = {}) {
  const { logPrefix = "Error in handler:", onError } = opts;
  return (message, sendResponse) => {
    produce(message)
      .then(sendResponse)
      .catch((error) => {
        console.error(logPrefix, error);
        sendResponse(onError ? onError(error) : { error: error.message });
      });
    return true;
  };
}

/** Extract `userId` from either `message.userId` or `message.data?.userId`. */
function extractUserId(message) {
  return message.userId || message.data?.userId;
}

/** Reject with `userId is required` when the field is missing. */
function withRequiredUserId(typeLabel, handler) {
  return (message, sendResponse) => {
    const userId = extractUserId(message);
    if (!userId) {
      console.error(`${typeLabel}: userId is missing from message`, message);
      sendResponse({ success: false, error: "userId is required" });
      return true;
    }
    return handler(userId, message, sendResponse);
  };
}

/**
 * Registry of `runtime.onMessage` handlers keyed by `message.type`.
 * Each handler MUST return `true` to keep the message channel open for async sendResponse,
 * even when its underlying work is synchronous — consistent return preserves the prior
 * "always keep channel open" behavior of the if-chain.
 */
const MESSAGE_HANDLERS = new Map([
  [
    "API_REQUEST",
    makeAsyncHandler((m) => handleApiRequest(m.data), {
      logPrefix: "Error handling API request:",
      onError: (e) => ({ error: e.message, status: 500 }),
    }),
  ],
  [
    "GET_RBLX_ACC",
    makeAsyncHandler(() => getRobloxAccount(), {
      logPrefix: "Error getting Roblox account:",
      onError: () => null,
    }),
  ],
  [
    "SET_ROBLOSECURITY_COOKIE",
    makeAsyncHandler(
      async (m) => {
        // Await the write so the response reflects the actual cookie set
        // result — .ROBLOSECURITY is the auth cookie and a false success
        // would mask a failed account switch.
        await browserAPI.cookies.set({
          url: "https://www.roblox.com",
          name: ".ROBLOSECURITY",
          value: m.data,
        });
        return { success: true, cookie: m.data };
      },
      {
        logPrefix: "Error setting ROBLOSECURITY cookie:",
        onError: (e) => ({ success: false, error: e.message }),
      },
    ),
  ],
  [
    "GET_AUTH_TOKEN",
    makeAsyncHandler(() => getAuthToken(), {
      logPrefix: "Error getting auth token:",
    }),
  ],
  [
    "DETECT_DEV",
    makeAsyncHandler(
      async () => ({ origin: await detectEnvironment() }),
      {
        logPrefix: "Error detecting environment:",
        onError: () => ({ origin: "https://theme.betterroblox.com" }),
      },
    ),
  ],
  [
    "GET_ROBLOX_USERS_DATA",
    makeAsyncHandler(
      async (m) => ({ success: true, users: await getRobloxUsersData(m.userIds) }),
      {
        logPrefix: "Error getting Roblox users data:",
        onError: (e) => ({ success: false, error: e.message }),
      },
    ),
  ],
  [
    "START_FRIEND_TRACKING",
    withRequiredUserId("START_FRIEND_TRACKING", (userId, _m, sendResponse) => {
      friendTrackingService
        .initializeTracking(userId)
        .then(sendResponse)
        .catch((error) => {
          console.error("Error starting friend tracking:", error);
          sendResponse({ success: false, error: error.message });
        });
      return true;
    }),
  ],
  [
    "STOP_FRIEND_TRACKING",
    withRequiredUserId("STOP_FRIEND_TRACKING", (userId, _m, sendResponse) => {
      friendTrackingService
        .stopTracking(userId)
        .then((result) => sendResponse({ success: true, ...result }))
        .catch((error) => {
          console.error("Error stopping friend tracking:", error);
          sendResponse({ success: false, error: error.message });
        });
      return true;
    }),
  ],
  [
    "GET_FRIEND_TRACKING_HISTORY",
    withRequiredUserId("GET_FRIEND_TRACKING_HISTORY", (userId, _m, sendResponse) => {
      friendTrackingService
        .getHistory(userId)
        .then((history) => sendResponse({ success: true, history }))
        .catch((error) => {
          console.error("Error getting friend tracking history:", error);
          sendResponse({ success: false, error: error.message });
        });
      return true;
    }),
  ],
  [
    "GET_PLAYTIME_SESSION",
    (_message, sendResponse) => {
      playtimeXpService
        .getCurrentSession()
        .then((session) => sendResponse({ success: true, session }))
        .catch((error) => {
          console.error("Error getting playtime session:", error);
          sendResponse({ success: false, error: error.message });
        });
      return true;
    },
  ],
  [
    "GET_PLAYTIME_HISTORY",
    (_message, sendResponse) => {
      playtimeXpService
        .getHistory()
        .then((history) => sendResponse({ success: true, history }))
        .catch((error) => {
          console.error("Error getting playtime history:", error);
          sendResponse({ success: false, error: error.message });
        });
      return true;
    },
  ],
]);

// Registered at module evaluation time: MV3 only delivers events that wake a
// terminated service worker to listeners added in the first synchronous turn.
// Registering this inside the (awaited) init flow dropped every message that
// arrived after an idle shutdown or during the multi-second init window.
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  const handler = MESSAGE_HANDLERS.get(message?.type);
  if (handler) {
    servicesReady.then(() => handler(message, sendResponse));
    return true; // keep the channel open while init finishes
  }
  // No matching handler — preserve prior fall-through behavior of returning true
  // so the runtime keeps the channel open even for unrecognized messages.
  return true;
});

// Environment detection function for theme server
async function detectEnvironment() {
  const developmentUrl = "http://localhost:5180";
  const betaUrl = "https://beta.betterroblox.com";
  const productionUrl = "https://theme.betterroblox.com";

  try {
    // Check user's environment preference first
    const settings = await browserAPI.storage.local.get([
      "themeEnvironment",
      "devModeEnabled",
    ]);

    // Support legacy devModeEnabled setting for backward compatibility
    let environment = settings.themeEnvironment;
    if (!environment && settings.devModeEnabled === true) {
      environment = "dev";
    }
    if (!environment) {
      environment = "production"; // Default to production
    }

    // If dev mode is selected, check if localhost is available
    if (environment === "dev") {
      console.log("Checking for development server at", developmentUrl);
      try {
        const response = await fetch(developmentUrl + "/home", {
          method: "HEAD", // Use HEAD to avoid downloading content
        });

        if (response.ok) {
          console.log("Development server detected, using localhost");
          return developmentUrl;
        }
      } catch (error) {
        console.log("Development server not available:", error.message);
        console.log("Falling back to production server");
        return productionUrl;
      }
    }

    // Return the appropriate URL based on environment
    switch (environment) {
      case "dev":
        return developmentUrl;
      case "beta":
        console.log("Using beta server");
        return betaUrl;
      case "production":
      default:
        console.log("Using production server");
        return productionUrl;
    }
  } catch (error) {
    console.error("Error detecting environment:", error);
    console.log("Falling back to production server");
    return productionUrl;
  }
}

// Function to get Roblox user data including usernames and thumbnails
async function getRobloxUsersData(userIds) {
  if (!userIds || !Array.isArray(userIds) || userIds.length === 0) {
    return [];
  }

  try {
    // Fetch user info for all user IDs
    const userInfoPromises = userIds.map(async (userId) => {
      try {
        const response = await fetch(
          `https://users.roblox.com/v1/users/${userId}`,
        );
        if (!response.ok) {
          console.warn(
            `Failed to fetch user info for ${userId}:`,
            response.status,
          );
          return null;
        }
        return await response.json();
      } catch (error) {
        console.warn(`Error fetching user info for ${userId}:`, error);
        return null;
      }
    });

    const userInfos = await Promise.all(userInfoPromises);
    const validUsers = userInfos.filter((user) => user !== null);

    // Fetch thumbnails for all valid users
    const thumbnailPromises = validUsers.map(async (user) => {
      try {
        const thumbnailResponse = await fetch(
          `https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=${user.id}&size=150x150&format=Png&isCircular=true`,
        );
        if (!thumbnailResponse.ok) {
          console.warn(
            `Failed to fetch thumbnail for ${user.id}:`,
            thumbnailResponse.status,
          );
          return { ...user, thumbnailUrl: null };
        }

        const thumbnailData = await thumbnailResponse.json();
        const thumbnailUrl =
          thumbnailData.data && thumbnailData.data.length > 0
            ? thumbnailData.data[0].imageUrl
            : null;

        return { ...user, thumbnailUrl };
      } catch (error) {
        console.warn(`Error fetching thumbnail for ${user.id}:`, error);
        return { ...user, thumbnailUrl: null };
      }
    });

    const usersWithThumbnails = await Promise.all(thumbnailPromises);

    console.log(
      `Successfully fetched data for ${usersWithThumbnails.length} users`,
    );
    return usersWithThumbnails;
  } catch (error) {
    console.error("Error in getRobloxUsersData:", error);
    throw error;
  }
}

async function getRobloxAccount() {
  const cookie = await browserAPI.cookies.get({
    url: "https://www.roblox.com",
    name: ".ROBLOSECURITY",
  });

  if (!cookie || !cookie.value) {
    return null;
  }
  const account = await fetch(
    "https://users.roblox.com/v1/users/authenticated",
  );

  if (!account.ok) {
    return null;
  }

  const accountData = await account.json();
  if (accountData?.errors) {
    return null;
  }

  accountData.cookie = cookie.value;

  return accountData;
}

browserAPI.cookies
  .get({
    url: "https://betterroblox.com",
    name: "refferrerCode",
  })
  .then((cookie) => {
    if (cookie?.value) {
      awardReferralCode(cookie.value);
    }
  });

function awardReferralCode(code) {
  browserAPI.cookies.set({
    url: "https://betterroblox.com",
    name: "refferrerCode",
    value: code,
  });
}
