/**
 * Broadcast a runtime message to every open Roblox tab.
 * Errors per-tab (tab closed, content script not loaded) are non-fatal and silently dropped;
 * caller awaits all sends.
 *
 * @param {string} messageType - the runtime message `type`
 * @param {*} data - payload sent in the message
 * @param {object} [meta] - extra fields merged at the top level of the message
 */
export async function notifyRobloxTabs(messageType, data, meta = {}) {
  const tabs = await chrome.tabs.query({ url: "*://*.roblox.com/*" });
  if (!tabs || !Array.isArray(tabs)) return;
  await Promise.all(
    tabs.map((tab) =>
      chrome.tabs
        .sendMessage(tab.id, { type: messageType, data, meta })
        .catch(() => {}), // tab closed/not ready — non-fatal
    ),
  );
}
