import storageManager from "../../utils/storageManager.js";
import friendsService from "../friends/friendsService.js";
import { FAST_API_BASE_URL } from "../../constants.js";

const SERVER_API_URL = `${FAST_API_BASE_URL}/api/user/public/batch-presence`;

// Optimization constants
const SERVER_SEND_INTERVAL = 60000; // 60 seconds — the old 10s value made every 45s presence poll send (6x the designed rate)
const BASE_BACKOFF_DELAY = 20000; // 20 seconds base backoff
const MAX_BACKOFF_DELAY = 300000; // 5 minutes maximum backoff

// Only send a friend whose presence CHANGED since last send — but re-send an
// unchanged one at least every HEARTBEAT_MS so the server's liveness window
// (~300s: online count + idle session sweep) never lapses. Offline (type 0) is
// dropped entirely (the server discards it anyway). Cuts payload + skips empty
// sends without losing any playtime / live-online / last-online accuracy.
const HEARTBEAT_MS = 180000; // 3 min — comfortably under the server's 300s window
const LASTSENT_TTL_MS = 600000; // forget users not seen in 10 min (bounds the map)

/** The presence facets the server keys on: online type + the game (rootPlaceId). */
function presenceStateKey(p) {
  const type = p?.userPresenceType ?? 0;
  const game = p?.rootPlaceId ?? p?.placeId ?? null;
  return { type, game: game ? String(game) : null };
}

class OptimizedServerSync {
  constructor() {
    this.name = "OptimizedServerSync"; // For logging

    // State management
    this.lastServerSend = 0;

    // Error handling and backoff behavior
    this.backoffAttempts = 0;
    this.nextSendTime = 0;
    this.serverHealthy = true;
    this.lastSuccessfulSend = 0;

    // Request state management
    this.isRequestInProgress = false;

    // userId -> { type, game, at } of the last presence we actually sent, so we
    // can skip unchanged friends until a heartbeat is due.
    this.lastSent = new Map();

    // For accurate time tracking, we maintain fixed intervals
    // Single attempt with backoff on failure - no retries
  }

  /**
   * Required method for presence service subscriber
   */
  async handlePresenceUpdate(presenceData) {
    try {
      const currentTime = Date.now();

      // FIXED INTERVAL: Always send every 60 seconds for accurate time tracking
      if (currentTime - this.lastServerSend >= SERVER_SEND_INTERVAL) {
        await this.processPresenceUpdate(presenceData);
        this.lastServerSend = currentTime;
      }
    } catch (error) {
      console.error("[OPTIMIZED SYNC] Error handling presence update:", error);
    }
  }

  /**
   * Process and optimize presence data before sending to server
   */
  async processPresenceUpdate(presenceData) {
    try {
      // Skip if offline or in backoff period
      if (this.shouldSkipServerSend()) {
        return;
      }

      // Convert presence data to array format expected by server
      const presences = Object.values(presenceData);

      // Include the current user + their friends (the user belongs in the
      // public presence DB / leaderboards too, not only their friends).
      const friendIds = await friendsService.getFriendIds();
      const selfId = friendsService.currentUserId
        ? parseInt(friendsService.currentUserId)
        : null;
      const friendsPresences = presences.filter((presence) => {
        const uid = parseInt(presence.userId);
        return uid === selfId || friendIds.includes(uid);
      });

      if (friendsPresences.length === 0) {
        return;
      }

      // Send only changed presences (+ a heartbeat for unchanged ones); drop
      // offline. The server reconstructs sessions / last-online from this stream
      // and only cares about online types, so this is lossless.
      const now = Date.now();
      const toSend = friendsPresences.filter((p) => {
        const { type, game } = presenceStateKey(p);
        if (type === 0) return false; // offline — server discards it anyway
        const prev = this.lastSent.get(String(p.userId));
        const changed = !prev || prev.type !== type || prev.game !== game;
        const heartbeatDue = prev && now - prev.at >= HEARTBEAT_MS;
        return changed || heartbeatDue;
      });

      // Nothing changed and no heartbeat due → skip the request entirely.
      if (toSend.length === 0) {
        return;
      }

      // Send to server with single attempt
      const success = await this.sendToServer(toSend);

      if (success) {
        for (const p of toSend) {
          const { type, game } = presenceStateKey(p);
          this.lastSent.set(String(p.userId), { type, game, at: now });
        }
        this.pruneLastSent(now);
        this.onSendSuccess();
      } else {
        this.onSendFailure();
      }
    } catch (error) {
      console.error(
        "[OPTIMIZED SYNC] Error processing presence update:",
        error
      );
      this.onSendFailure();
    }
  }

  /**
   * Forget users we haven't sent in a while (left the friends list / long
   * offline) so lastSent can't grow without bound.
   */
  pruneLastSent(now) {
    for (const [uid, info] of this.lastSent) {
      if (now - info.at > LASTSENT_TTL_MS) this.lastSent.delete(uid);
    }
  }

  /**
   * Check if we should skip sending to server
   */
  shouldSkipServerSend() {
    const currentTime = Date.now();

    // Skip if previous request is still in progress
    if (this.isRequestInProgress) {
      return true;
    }

    // Skip if we're in backoff period
    if (currentTime < this.nextSendTime) {
      const waitTime = Math.round((this.nextSendTime - currentTime) / 1000);
      console.log(
        `[OPTIMIZED SYNC] Skipping - in backoff period (${waitTime}s remaining)`
      );
      return true;
    }

    return false;
  }

  /**
   * Send data to server with single attempt
   */
  async sendToServer(presences) {
    // Set request in progress flag
    this.isRequestInProgress = true;

    try {
      const response = await fetch(SERVER_API_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          presences: presences,
        }),
      });

      if (response.ok) {
        const result = await response.json();
        return true;
      }

      // Handle specific HTTP errors for backoff timing
      if (response.status === 429) {
        // Rate limited - use server's retry-after header
        const retryAfter = parseInt(
          response.headers.get("retry-after") || "60",
          10
        );
        console.warn(
          `[OPTIMIZED SYNC] Rate limited, backing off for ${retryAfter}s`
        );
        this.nextSendTime = Date.now() + retryAfter * 1000;
        return false;
      }

      if (response.status === 503) {
        // Service unavailable (circuit breaker)
        console.warn(
          "[OPTIMIZED SYNC] Server circuit breaker is open, backing off for 60s"
        );
        this.nextSendTime = Date.now() + 60000; // 1 minute backoff
        return false;
      }

      // Any other error - use exponential backoff
      console.warn(
        `[OPTIMIZED SYNC] Server error ${response.status}, backing off`
      );
      return false;
    } catch (error) {
      console.warn(`[OPTIMIZED SYNC] Network error:`, error.message);
      return false;
    } finally {
      // Always clear the request in progress flag
      this.isRequestInProgress = false;
    }
  }

  /**
   * Handle successful send
   */
  onSendSuccess() {
    this.serverHealthy = true;
    this.backoffAttempts = 0; // Reset backoff on success
    this.lastSuccessfulSend = Date.now();
    this.nextSendTime = 0; // Clear any backoff

    console.log("[OPTIMIZED SYNC] Send successful");
  }

  /**
   * Handle failed send
   */
  onSendFailure() {
    this.serverHealthy = false;
    this.backoffAttempts++;

    // Set exponential backoff (only if not already set by specific error handling)
    if (this.nextSendTime <= Date.now()) {
      const backoffDelay = Math.min(
        BASE_BACKOFF_DELAY * Math.pow(2, this.backoffAttempts - 1),
        MAX_BACKOFF_DELAY
      );
      this.nextSendTime = Date.now() + backoffDelay;

      console.log(
        `[OPTIMIZED SYNC] Send failed, backing off for ${Math.round(
          backoffDelay / 1000
        )}s`
      );
    }
  }

  /**
   * Initialize the service
   */
  async initialize() {
    console.log("[OPTIMIZED SYNC] Simple server sync service initialized");
    console.log(
      `[OPTIMIZED SYNC] Fixed interval: ${SERVER_SEND_INTERVAL}ms, single attempt with backoff`
    );
  }
}

// Create singleton instance
const optimizedServerSync = new OptimizedServerSync();

export default optimizedServerSync;
