import { initBackgroundScriptV2 } from "./betterblox-background/loader.js";

initBackgroundScriptV2();

// Add this to your existing listeners
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "GET_PRESENCE_FOR_USERS") {
    (async () => {
      sendResponse(await getPresenceForUsers(message.data.userIds));
    })();
    return true;
  }
});

async function getPresenceForUsers(userIds) {
  const response = await fetch(`https://presence.roblox.com/v1/presence/users`, {
    method: "POST",
    body: JSON.stringify({ userIds: userIds }),
  });
  return await response.json();
}
