import { browserAPI } from "../../utils/browserAPI.js";

function generateRandomString() {
  return (
    Math.random().toString(36).substring(2, 15) +
    Math.random().toString(36).substring(2, 15)
  );
}

function extractCodeAndState(location) {
  try {
    const url = new URL(location);
    const code = url.searchParams.get("code");
    const state = url.searchParams.get("state");

    return { code, state };
  } catch (error) {
    throw new Error("Failed to parse location URL");
  }
}

async function getXsrfToken(clientId, state, nonce, userId) {
  const response = await fetch(
    "https://apis.roblox.com/oauth/v1/authorizations",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        clientId: clientId,
        responseTypes: ["Code"],
        redirectUri: "http://localhost:4949/auth/callback",
        scopes: [
          {
            scopeType: "openid",
            operations: ["read"],
          },
          {
            scopeType: "profile",
            operations: ["read"],
          },
        ],
        state: state,
        nonce: nonce,
        resourceInfos: [
          {
            owner: {
              id: userId,
              type: "User",
            },
            resources: {},
          },
        ],
      }),
    },
  );

  const xsrfToken = response.headers.get("x-csrf-token");
  if (!xsrfToken) {
    throw new Error("Failed to get XSRF token from response headers");
  }

  return xsrfToken;
}

export default async function getAuthToken() {
  try {
    // Check if we have a stored token and if it's still valid
    const storedToken = await getStoredToken();
    if (storedToken && (await isTokenValid(storedToken.accessToken))) {
      console.log("Using stored valid token");
      return storedToken;
    }

    // If no valid token, get a new one
    console.log("Getting new auth token");

    // Generate random values for the auth token
    const state = generateRandomString();
    const nonce = generateRandomString();
    const originalState = state; // Store original state for verification

    const clientId = "1298491012038790056";

    const userIdRequest = await fetch(
      "https://users.roblox.com/v1/users/authenticated",
      {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      },
    );
    const userIdJson = await userIdRequest.json();
    const userId = userIdJson.id;
    if (!userId) {
      throw new Error("Failed to get user id");
    }

    // Get the XSRF token using the same body
    const xsrfToken = await getXsrfToken(clientId, state, nonce, userId);

    // Now make the POST request with the XSRF token
    const response = await fetch(
      "https://apis.roblox.com/oauth/v1/authorizations",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-csrf-token": xsrfToken,
        },
        body: JSON.stringify({
          clientId: clientId,
          responseTypes: ["Code"],
          redirectUri: "http://localhost:4949/auth/callback",
          scopes: [
            {
              scopeType: "openid",
              operations: ["read"],
            },
            {
              scopeType: "profile",
              operations: ["read"],
            },
          ],
          state: state,
          nonce: nonce,
          resourceInfos: [
            {
              owner: {
                id: userId,
                type: "User",
              },
              resources: {},
            },
          ],
        }),
      },
    );

    const result = await response.json();

    // Extract code and state from the location URL
    if (result.location) {
      const { code, state: returnedState } = extractCodeAndState(
        result.location,
      );

      // Exchange code for access token
      const tokenResponse = await exchangeCodeForToken(
        code,
        originalState,
        nonce,
      );

      if (tokenResponse && tokenResponse.success) {
        // Store the token for future use
        await storeToken(tokenResponse);
        return tokenResponse;
      }
    }

    return result;
  } catch (error) {
    console.error("Error getting auth token:", error);
    throw error;
  }
}

async function exchangeCodeForToken(code, state, nonce) {
  try {
    const url = new URL("https://api.betterroblox.com/auth/authenticate");
    url.searchParams.set("code", code);
    url.searchParams.set("state", state);
    url.searchParams.set("original_state", state);
    url.searchParams.set("nonce", nonce);

    const response = await fetch(url.toString(), {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
      },
    });

    if (!response.ok) {
      throw new Error(`Token exchange failed: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error("Error exchanging code for token:", error);
    return null;
  }
}

async function isTokenValid(accessToken) {
  try {
    const url = new URL("https://api.betterroblox.com/auth/status");
    url.searchParams.set("token", accessToken);

    const response = await fetch(url.toString(), {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
      },
    });

    if (!response.ok) {
      return false;
    }

    const result = await response.json();
    return result.authenticated;
  } catch (error) {
    console.error("Error checking token validity:", error);
    return false;
  }
}

async function getStoredToken() {
  try {
    const result = await browserAPI.storage.local.get(["authToken"]);
    return result.authToken || null;
  } catch (error) {
    console.error("Error getting stored token:", error);
    return null;
  }
}

async function storeToken(tokenData) {
  try {
    await browserAPI.storage.local.set({ authToken: tokenData });
    console.log("Token stored successfully");
  } catch (error) {
    console.error("Error storing token:", error);
  }
}
