import storageManager from "../../utils/storageManager.js";
import authManager from "../authentication/getAuthStatus.js";
import { FAST_API_BASE_URL } from "../../constants.js";
import { parseRetryAfterMs } from "../../utils/retryAfter.js";

// Scheduler intervals
const DISCOVERY_CHECK_INTERVAL = 60 * 1000; // 60s normal poll for available tasks
const DISCOVERY_BACKOFF_AFTER_SERVERS = 5 * 60 * 1000; // 5min cooldown after a server fetch (rate-limit friendly)
const INITIAL_CHECK_DELAY_MS = 1000; // first run after scheduler start

// Server pagination
const SERVERS_PER_PAGE = 100; // Roblox API max
const MAX_PAGINATION_ATTEMPTS = 10; // bounds runaway loops if cursor never terminates
const INTER_REQUEST_DELAY_MS = 100; // gentle throttle between pages
const RETRY_BACKOFF_MS = 2000; // wait before retry after a transient fetch error
const RATE_LIMIT_STATUS = 429;
const DEFAULT_RETRY_AFTER_SECONDS = 5; // fallback when Roblox omits Retry-After header

const SERVER_API_URL = `${FAST_API_BASE_URL}/api/discovery`;

// chrome.alarms survives MV3 service-worker unloads; setTimeout does not.
// Chrome clamps periodInMinutes to a 1-minute floor in production, so the
// alarm fires ~every minute. The dynamic backoff (5-min cooldown after a
// server fetch) is implemented by gating checkForTask on a stored timestamp
// rather than by changing the alarm period.
const DISCOVERY_ALARM_NAME = "gameDiscoveryCheck";

class GameDiscoveryService {
  constructor() {
    this.isRunning = false;
    this.currentTask = null;
    this.extensionId = null;
    this.wasAuthenticated = false; // Track previous auth state
    this.isRequestInProgress = false; // Prevent overlapping requests
    this.nextAllowedCheckMs = 0; // earliest time the next check may run (backoff gate)
    this.alarmListener = null;
  }

  async initialize() {
    // console.log("[DISCOVERY] Initializing discovery service...");
    this.startDiscoveryScheduler(); // Always start the scheduler
  }

  /**
   * Get or update the extension ID based on authenticated user
   */
  async updateExtensionId() {
    try {
      const authData = await authManager.getAuthData();
      if (authData && authData.id) {
        this.extensionId = `user-${authData.id}`;
        // console.log(
        //   `[DISCOVERY] Using player ID as extension identifier: ${this.extensionId}`
        // );
        return true;
      } else {
        // console.log("[DISCOVERY] No authenticated user found");
        this.extensionId = null;
        return false;
      }
    } catch (error) {
      // console.error("[DISCOVERY] Error getting auth data:", error);
      this.extensionId = null;
      return false;
    }
  }

  /**
   * Start the scheduler to periodically check for discovery tasks
   */
  startDiscoveryScheduler() {
    if (this.isRunning) {
      return; // Already running
    }

    this.isRunning = true;
    // console.log(
    //   "[DISCOVERY] Starting discovery task scheduler (60s intervals by default)"
    // );

    // Periodic alarm survives service-worker suspension (unlike setTimeout).
    chrome.alarms.create(DISCOVERY_ALARM_NAME, {
      periodInMinutes: DISCOVERY_CHECK_INTERVAL / 60000,
    });

    if (!this.alarmListener) {
      this.alarmListener = (alarm) => {
        if (alarm.name === DISCOVERY_ALARM_NAME) {
          this.checkForTask();
        }
      };
      chrome.alarms.onAlarm.addListener(this.alarmListener);
    }

    // Kick off the first run shortly after start (the alarm's first fire can
    // be up to a minute away).
    setTimeout(() => this.checkForTask(), INITIAL_CHECK_DELAY_MS);
  }

  /**
   * Stop the scheduler
   */
  stopDiscoveryScheduler() {
    chrome.alarms.clear(DISCOVERY_ALARM_NAME);
    if (this.alarmListener) {
      chrome.alarms.onAlarm.removeListener(this.alarmListener);
      this.alarmListener = null;
    }
    this.isRunning = false;
    this.currentTask = null;
    // console.log("[DISCOVERY] Discovery task scheduler stopped");
  }

  /**
   * Check for available discovery tasks
   */
  async checkForTask() {
    if (!this.isRunning || this.currentTask || this.isRequestInProgress) {
      return;
    }

    // Backoff gate: the alarm fires ~every minute, but skip this run if the
    // server-fetch cooldown has not elapsed yet.
    if (Date.now() < this.nextAllowedCheckMs) {
      return;
    }

    this.isRequestInProgress = true;

    try {
      // Quick auth check
      if (!(await authManager.isAuthenticated())) {
        this.wasAuthenticated = false;
        this.scheduleNextCheck();
        return;
      }

      // Update extension ID if needed
      if (!this.extensionId && !(await this.updateExtensionId())) {
        this.scheduleNextCheck();
        return;
      }

      this.wasAuthenticated = true;

      // Get task from server
      const response = await fetch(`${SERVER_API_URL}/get-task`, {
        method: "GET",
        headers: { "X-Extension-Id": this.extensionId },
      });

      if (!response.ok) {
        this.scheduleNextCheck();
        return;
      }

      const result = await response.json();
      if (!result.success || !result.hasTask) {
        this.scheduleNextCheck();
        return;
      }

      // Process the task
      this.currentTask = result.task;
      const requiresServerUpdate = this.currentTask.requiresServerUpdate;

      console.log(`[DISCOVERY] Processing game ${this.currentTask.gameId} (${this.currentTask.activePlayers} players)${requiresServerUpdate ? " - SERVER FETCH REQUIRED" : ""}`);

      const hadServerFetch = await this.processTask(this.currentTask);
      this.scheduleNextCheck(hadServerFetch);
    } catch (error) {
      console.error("[DISCOVERY] Error in task check:", error);
      this.scheduleNextCheck();
    } finally {
      this.isRequestInProgress = false;
    }
  }

  /**
   * Process a discovery task - OPTIMIZED with server fetch tracking
   */
  async processTask(task) {
    let hadServerFetch = false;

    try {
      // Step 1: Get universeId from placeId
      const universeResponse = await fetch(`https://apis.roblox.com/universes/v1/places/${task.gameId}/universe`);

      if (!universeResponse.ok) {
        throw new Error(`Failed to get universeId: ${universeResponse.statusText}`);
      }

      const universeData = await universeResponse.json();
      let universeId = universeData.universeId;

      if (!universeId) {
        universeId = task.gameId;
      }

      // Step 2: Get game details
      const gameDetailsResponse = await fetch(`https://games.roblox.com/v1/games?universeIds=${universeId}`);

      if (!gameDetailsResponse.ok) {
        throw new Error(`Failed to get game details: ${gameDetailsResponse.statusText}`);
      }

      const gameDetailsData = await gameDetailsResponse.json();
      if (!gameDetailsData.data?.length) {
        throw new Error("No game data returned");
      }

      const gameDetails = gameDetailsData.data[0];
      const taskResult = {
        gameId: task.gameId.toString(),
        gameData: {
          activePlayers: gameDetails.playing,
          updated: gameDetails.updated,
        },
      };

      // Fetch servers only if required (>=500 players)
      if (task.requiresServerUpdate) {
        try {
          const servers = await this.fetchAllServers(task.gameId);
          taskResult.serverData = { servers };
          hadServerFetch = true; // Mark that we performed server fetch
          console.log(`[DISCOVERY] Fetched ${servers.length} servers for game ${task.gameId} - BACKOFF TRIGGERED`);
        } catch (serverError) {
          console.warn(`[DISCOVERY] Failed to fetch servers for game ${task.gameId}:`, serverError.message);
          // Still count as server fetch attempt for backoff
          hadServerFetch = true;
        }
      }

      // Submit results
      await this.submitTask(taskResult);
      this.currentTask = null;

      return hadServerFetch;
    } catch (error) {
      this.currentTask = null;
      console.warn(`[DISCOVERY] Error processing game ${task.gameId}:`, error.message);

      try {
        await this.submitTask({
          gameId: task.gameId.toString(),
          gameData: {
            isError: true,
            error: error.message,
            activePlayers: 0,
            updated: null,
          },
        });
      } catch (error) {
        console.error(`[DISCOVERY] Error submitting failed task for game ${task.gameId}:`, error.message);
      }

      return hadServerFetch;
    }
  }

  /**
   * Fetch all servers for a game
   */
  async fetchAllServers(placeId) {
    let allServers = [];
    let cursor = "";
    let attempts = 0;

    while (attempts < MAX_PAGINATION_ATTEMPTS) {
      try {
        const url = `https://games.roblox.com/v1/games/${placeId}/servers/0?sortOrder=2&excludeFullGames=true&limit=${SERVERS_PER_PAGE}${cursor ? `&cursor=${cursor}` : ""}`;

        const response = await fetch(url);

        if (response.status === RATE_LIMIT_STATUS) {
          const waitMs = parseRetryAfterMs(response, DEFAULT_RETRY_AFTER_SECONDS * 1000);
          await new Promise((resolve) => setTimeout(resolve, waitMs));
          continue;
        }

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const data = await response.json();

        if (data.data && data.data.length > 0) {
          allServers = allServers.concat(data.data);
        }

        // Check if we've reached the end
        if (!data.nextPageCursor) {
          break;
        }

        cursor = data.nextPageCursor;
        attempts++;

        // Small delay between requests to be respectful
        await new Promise((resolve) => setTimeout(resolve, INTER_REQUEST_DELAY_MS));
      } catch (error) {
        attempts++;

        if (attempts >= MAX_PAGINATION_ATTEMPTS) {
          throw error;
        }

        // Wait before retrying
        await new Promise((resolve) => setTimeout(resolve, RETRY_BACKOFF_MS));
      }
    }

    return allServers;
  }

  /**
   * Submit completed task results to server
   */
  async submitTask(taskResult) {
    try {
      console.log(`[DISCOVERY] Submitting task results for game ${taskResult.gameId} with extension ID: ${this.extensionId}`);

      const response = await fetch(`${SERVER_API_URL}/submit-task`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Extension-Id": this.extensionId,
        },
        body: JSON.stringify(taskResult),
      });

      const result = await response.json();

      if (!response.ok) {
        console.error(`[DISCOVERY] Server rejected submission (${response.status}):`, result.error || response.statusText);
        throw new Error(`HTTP ${response.status}: ${result.error || response.statusText}`);
      }

      if (result.success) {
        console.log(`[DISCOVERY] Task completed successfully for game ${taskResult.gameId}`);
      } else {
        console.error(`[DISCOVERY] Server rejected task submission:`, result.error);
      }

      // Clear current task
      this.currentTask = null;
    } catch (error) {
      console.error(`[DISCOVERY] Error submitting task for game ${taskResult.gameId}:`, error.message);
      // Clear current task even on error so we can get new ones
      this.currentTask = null;
    }
  }

  /**
   * Schedule the next task check - DYNAMIC INTERVALS
   */
  scheduleNextCheck(hadServerFetch = false) {
    if (!this.isRunning) return;

    let interval;
    let intervalText;

    if (hadServerFetch) {
      interval = DISCOVERY_BACKOFF_AFTER_SERVERS;
      intervalText = `${DISCOVERY_BACKOFF_AFTER_SERVERS / 60000} minutes (server fetch backoff)`;
    } else {
      interval = DISCOVERY_CHECK_INTERVAL;
      intervalText = `${DISCOVERY_CHECK_INTERVAL / 1000} seconds (normal)`;
    }

    // The recurring chrome.alarm drives the cadence; record when the next
    // check is allowed so the per-minute alarm fires honor the dynamic
    // backoff instead of relying on an in-memory setTimeout that dies on
    // service-worker suspension.
    this.nextAllowedCheckMs = Date.now() + interval;
    console.log(`[DISCOVERY] Next check in ${intervalText}`);
  }
}

// Create singleton instance
const gameDiscoveryService = new GameDiscoveryService();

export default gameDiscoveryService;
