import storageManager from "../../utils/storageManager.js";

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

class AutoJoinChecker {
  constructor() {
    this.previousPresenceData = new Map();
    this.checkInterval = null;
    this.lastNotificationTime = 0; // Track last notification time
    this.NOTIFICATION_DELAY = 2000; // 2 seconds in milliseconds
    this.currentlyPlayingWith = null; // Track who we're playing with
    this.initializeNotificationListener();
  }

  async handlePresenceUpdate(presenceData) {
    try {
      // Get list of users to auto join
      const autoJoinList = await storageManager.get("autoJoin", []);
      if (!autoJoinList || !Array.isArray(autoJoinList) || !autoJoinList.length) return;

      const presenceDataFiltered = Object.values(presenceData).filter(
        (presence) => autoJoinList.includes(presence.userId.toString())
      );

      const authStatus = await storageManager.get("betterblox_auth_status", {
        id: null,
        name: null,
        displayName: null,
        lastChecked: null,
      });
      const userId = authStatus?.id;
      if (!userId) return;

      const myPresence = presenceData[userId];
      if (!myPresence) return;

      // Check if we're still playing with the same friend
      if (this.currentlyPlayingWith) {
        const playingWithPresence = presenceData[this.currentlyPlayingWith];

        // If we're no longer in the same game with that friend, clear the flag
        if (
          !playingWithPresence ||
          myPresence.userPresenceType !== 2 ||
          playingWithPresence.userPresenceType !== 2 ||
          myPresence.gameId !== playingWithPresence.gameId
        ) {
          this.currentlyPlayingWith = null;
        } else {
          console.log(
            "[PLAY NOTIFICATION] Still playing with friend, suppressing notifications"
          );
          return; // Skip notifications while playing with a friend
        }
      }

      // Check each auto-join friend
      for (const presence of presenceDataFiltered) {
        // Skip if it's the current user or not in auto join list
        if (presence.userId.toString() === userId) continue;

        const previousPresence = this.previousPresenceData.get(presence.userId);

        // Check if friend is in a game
        if (presence.userPresenceType === 2) {
          const serverChanged = previousPresence?.gameId !== presence.gameId;
          const differentGame =
            myPresence.userPresenceType !== 2 ||
            myPresence.gameId !== presence.gameId;

          // If we're in the same game as this friend, set the flag
          if (!differentGame) {
            console.log(
              "[PLAY NOTIFICATION] Playing with friend, suppressing other notifications"
            );
            this.currentlyPlayingWith = presence.userId;
            return; // Stop checking other friends
          }

          // Notify if friend is in a different game/server
          if (serverChanged && differentGame) {
            await this.sendServerChangeNotification(presence.userId, presence);
          }
        }

        // Update previous presence data
        this.previousPresenceData.set(presence.userId, presence);
      }
    } catch (error) {
      console.error("[PLAY NOTIFICATION] Error checking auto join:", error);
    }
  }

  initializeNotificationListener() {
    // Handle button clicks (Chrome/Edge/Opera)
    chrome.notifications.onButtonClicked.addListener(
      (notificationId, buttonIndex) => {
        const parts = notificationId.split(":");
        const userId = parts[1];
        const placeId = parts[2];
        const serverId = parts[3] || "";

        if (buttonIndex === 0) {
          // Join Game button clicked
          this.joinGame(placeId, serverId);
        } else if (buttonIndex === 1) {
          // Stop Notifications button clicked
          this.disableAutoJoinForUser(userId).then(() => {
            console.log(`Auto-join disabled for user ${userId}`);
          });
        }

        chrome.notifications.clear(notificationId);
      }
    );

    // Handle notification clicks (Firefox)
    chrome.notifications.onClicked.addListener((notificationId) => {
      if (notificationId.startsWith("join:")) {
        const parts = notificationId.split(":");
        const placeId = parts[2];
        const serverId = parts[3] || "";

        this.joinGame(placeId, serverId);
        chrome.notifications.clear(notificationId);
      }
    });
  }

  // New helper method to handle game joining
  joinGame(placeId, serverId) {
    chrome.tabs.create({
      url: `https://www.roblox.com/games/${placeId}/#!/game-instances?betterBloxJoin=${serverId}&placeid=${placeId}`,
    });
  }

  async disableAutoJoinForUser(userId) {
    try {
      if (!userId) {
        console.error("No userId provided to disable auto-join");
        return;
      }

      const autoJoinList = await storageManager.get("autoJoin", []);
      console.log("Current auto-join list:", autoJoinList);

      // Ensure autoJoinList is an array
      const safeAutoJoinList = Array.isArray(autoJoinList) ? autoJoinList : [];
      
      // Convert both to strings for comparison
      const userIdStr = userId.toString();
      const updatedList = safeAutoJoinList.filter(
        (id) => id.toString() !== userIdStr
      );

      console.log("Updated auto-join list:", updatedList);
      await storageManager.set("autoJoin", updatedList);
      return true;
    } catch (error) {
      console.error("Failed to disable auto-join:", error);
      return false;
    }
  }

  async sendServerChangeNotification(userId, presence) {
    try {
      this.lastNotificationTime = Date.now();

      const [userInfo, avatarData] = await Promise.all([
        getUserInfo(userId),
        getUserThumbnail(userId),
      ]);

      const avatarUrl = avatarData.data?.[0]?.imageUrl || "/icons/icon48.png";
      let message = `${userInfo.displayName} (@${userInfo.name}) is playing`;

      if (presence.lastLocation) {
        message += `\nGame: ${presence.lastLocation}`;
      }

      const notificationId = `join:${userId}:${presence.placeId}:${presence.gameId}`;

      // Create browser-compatible notification options
      const notificationOptions = {
        type: "basic",
        iconUrl: avatarUrl,
        title: "Friend Playing Game",
        message: message,
      };

      // Add browser-specific properties
      if (
        chrome.runtime.getManifest().manifest_version === 3 &&
        !chrome.runtime.getManifest()?.browser_specific_settings?.gecko
      ) {
        // Chrome/Edge/Opera: Add buttons and other properties
        Object.assign(notificationOptions, {
          buttons: [{ title: "Join Game" }, { title: "Stop Notifications" }],
          priority: 2,
          silent: true,
        });
      } else {
        // Firefox: Add message about clicking
        notificationOptions.message += "\n\nClick to join game";
      }

      chrome.notifications.create(notificationId, notificationOptions);

      // Auto-dismiss after 15 seconds
      setTimeout(() => {
        chrome.notifications.clear(notificationId);
      }, 15000);

      await delay(this.NOTIFICATION_DELAY);
    } catch (error) {
      console.error(`Failed to create notification for user ${userId}:`, error);
    }
  }
}

async function getUserInfo(userId) {
  if (!userId) {
    console.log("[ONLINE NOTIFICATION] No user id provided");
    return null;
  }

  const response = await fetch(`https://users.roblox.com/v1/users/${userId}`, {
    method: "GET",
  });

  if (!response.ok) {
    console.error(
      "[ONLINE NOTIFICATION] Failed to fetch user info:",
      response.statusText
    );
    return null;
  }

  const data = await response.json();
  return data;
}

async function getUserThumbnail(
  userId,
  type = "AvatarHeadShot",
  size = "420x420"
) {
  if (!userId) {
    console.log("[ONLINE NOTIFICATION] No user id provided");
    return null;
  }

  const response = await fetch(
    `https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=${userId}&size=${size}&format=Png`,
    {
      method: "GET",
    }
  );

  if (!response.ok) {
    console.error(
      "[ONLINE NOTIFICATION] Failed to fetch user info:",
      response.statusText
    );
    return null;
  }

  const data = await response.json();
  return data;
}

const autoJoinChecker = new AutoJoinChecker();
export default autoJoinChecker;
