import storageManager from "../../utils/storageManager.js";

const TRACKER_STORAGE_KEY = "betterblox_presence_tracker_v2";

class PresenceTracker {
  constructor() {
    this.trackerData = {};
    this.ready = false;
    // Hold the init() promise so callers can await readiness. The constructor
    // cannot await, so an early presence update could otherwise run against
    // the default empty trackerData and persist it — wiping stored history.
    this.initPromise = this.init();
  }

  async init() {
    console.log("[TRACKER] Presence Tracker initializing");

    // Load existing data from storage
    const trackerData = await storageManager.get(TRACKER_STORAGE_KEY, {});

    this.trackerData = trackerData;

    // Migrate existing data to new structure
    await this.migrateData();

    this.ready = true;

    console.log(
      "[TRACKER] Presence Tracker initialized with data for",
      Object.keys(this.trackerData).length,
      "users",
    );
  }

  async migrateData() {
    let migrated = false;
    const currentTime = new Date().getTime();

    for (const userId in this.trackerData) {
      const userData = this.trackerData[userId];

      // Migrate lastOnline from number to object
      if (
        userData.lastOnline !== null &&
        typeof userData.lastOnline === "number"
      ) {
        const oldTimestamp = userData.lastOnline;
        userData.lastOnline = {
          timestamp: oldTimestamp,
          gameId: null,
          gameName: null,
          sessionDuration: 0,
          presenceType: userData.presenceType || 0,
        };
        migrated = true;
      } else if (
        userData.lastOnline === null ||
        !userData.lastOnline.timestamp
      ) {
        // Initialize if null or invalid structure
        userData.lastOnline = {
          timestamp: null,
          gameId: null,
          gameName: null,
          sessionDuration: 0,
          presenceType: 0,
        };
        migrated = true;
      }

      // Migrate game history - add lastPlayed and sessions arrays
      if (userData.gameHistory && userData.gameHistory.games) {
        for (const placeId in userData.gameHistory.games) {
          const game = userData.gameHistory.games[placeId];

          // Initialize lastPlayed if missing
          if (game.lastPlayed === undefined) {
            game.lastPlayed = userData.timeStats?.lastUpdate || currentTime;
            migrated = true;
          }

          // Initialize sessions array if missing
          if (!Array.isArray(game.sessions)) {
            game.sessions = [];
            migrated = true;
          }
        }
      }

      // Initialize website and studio sessions arrays if missing
      if (!Array.isArray(userData.websiteSessions)) {
        userData.websiteSessions = [];
        migrated = true;
      }
      if (!Array.isArray(userData.studioSessions)) {
        userData.studioSessions = [];
        migrated = true;
      }
    }

    if (migrated) {
      console.log("[TRACKER] Data migration completed");
      await storageManager.set(TRACKER_STORAGE_KEY, this.trackerData);
    }
  }

  // Method to be called directly from the FriendsPresenceManager
  async handlePresenceUpdate(presenceData) {
    // Wait for the initial storage load before touching trackerData; running
    // against the default {} and persisting it would wipe accumulated history.
    if (!this.ready) await this.initPromise;

    console.log(
      "[TRACKER] Processing presence update with data for",
      Object.keys(presenceData).length,
      "users",
    );

    // Process each user's presence data
    for (const userId in presenceData) {
      await this.updateUserTrackingData(userId, presenceData[userId]);
    }

    // Save updated data
    await this.notifyTrackingData();
  }

  // Helper function to get time spent in the current day from a time range
  getTimeInCurrentDay(startTime, endTime, today) {
    // If both times are in the same day (today), return the full duration
    if (startTime >= today) {
      return endTime - startTime;
    }
    // If startTime is before today, only count time from today onwards
    if (endTime >= today) {
      return endTime - today;
    }
    // If both are before today, return 0
    return 0;
  }

  async updateUserTrackingData(userId, newPresence) {
    const currentTime = new Date().getTime();
    const today = new Date().setHours(0, 0, 0, 0);

    // Initialize tracking data for this user if it doesn't exist
    if (!this.trackerData[userId]) {
      this.trackerData[userId] = {
        timeStats: {
          daily: {
            game: 0,
            website: 0,
            studio: 0,
            lastReset: today,
          },
          total: {
            game: 0,
            website: 0,
            studio: 0,
          },
          lastUpdate: currentTime,
          lastType: 0,
        },
        lastOnline: {
          timestamp: null,
          gameId: null,
          gameName: null,
          sessionDuration: 0,
          presenceType: 0,
        },
        gameHistory: {
          currentGame: null,
          currentGameName: null,
          gameStartTime: null,
          games: {},
        },
        websiteSessions: [],
        studioSessions: [],
        websiteStartTime: null,
        studioStartTime: null,
        presenceType: 0,
      };
    }

    const trackerDataOld = this.trackerData[userId];

    // Check if user was online before and is online now
    const isOnline = newPresence.userPresenceType > 0;

    // Calculate time spent since last update
    let timeSpent = currentTime - trackerDataOld.timeStats.lastUpdate;
    if (timeSpent > 120000) {
      // Cap at 2 minutes to avoid counting large offline periods
      timeSpent = 0;
    }

    // Check if we need to reset daily stats
    if (trackerDataOld.timeStats.daily.lastReset < today) {
      console.log("[TRACKER] Resetting daily stats for user", userId);
      // Reset all daily stats
      this.trackerData[userId].timeStats.daily = {
        game: 0,
        website: 0,
        studio: 0,
        lastReset: today,
      };

      // Reset daily stats for all games

      Object.keys(this.trackerData[userId].gameHistory.games).forEach(
        (rootPlaceId) => {
          this.trackerData[userId].gameHistory.games[rootPlaceId].dailyTime = 0;
        },
      );

      // Reset current game tracking
      this.trackerData[userId].gameHistory.currentGame = null;
      this.trackerData[userId].gameHistory.gameStartTime = null;
      this.trackerData[userId].gameHistory.currentGameName = null;
    }

    // Update time stats based on presence type
    // Only count time spent in the current day to handle sessions spanning multiple days
    if (timeSpent > 0) {
      const categoryMap = {
        1: "website",
        2: "game",
        3: "studio",
      };

      const category = categoryMap[newPresence.userPresenceType];
      if (category) {
        // Calculate how much of timeSpent was in the current day
        const lastUpdate = trackerDataOld.timeStats.lastUpdate;
        const timeInCurrentDay = this.getTimeInCurrentDay(
          lastUpdate,
          currentTime,
          today,
        );

        // Add only today's portion to daily stats, but full timeSpent to total
        this.trackerData[userId].timeStats.daily[category] += timeInCurrentDay;
        this.trackerData[userId].timeStats.total[category] += timeSpent;
      }
    }

    const gameHistoryData = this.updateGameData(
      userId,
      newPresence,
      currentTime,
      timeSpent,
      today,
      trackerDataOld.timeStats.lastUpdate,
    );

    // Update website and studio session tracking
    this.updateWebsiteStudioSessions(
      userId,
      newPresence,
      currentTime,
      timeSpent,
    );

    // Update tracking info
    trackerDataOld.timeStats.lastUpdate = currentTime;

    // Update online status tracking (lastOnline is now handled in updateGameData)
    this.trackerData[userId] = {
      ...trackerDataOld,
      gameHistory: gameHistoryData,
      presenceType: newPresence.userPresenceType,
      lastLocation: newPresence.lastLocation,
      placeId: newPresence.placeId,
      rootPlaceId: newPresence.rootPlaceId,
      gameId: newPresence.gameId,
      universeId: newPresence.universeId,
      userId: newPresence.userId,
    };
  }

  updateGameData(
    userId,
    newPresence,
    currentTime,
    timeSpent,
    today,
    lastUpdate,
  ) {
    const gameHistoryData = this.trackerData[userId].gameHistory;
    const oldPresenceType = this.trackerData[userId].presenceType;
    const MAX_SESSIONS_PER_GAME = 50;
    const MAX_GAMES_PER_USER = 100;

    try {
      // Check if user stopped playing a game
      if (oldPresenceType === 2 && newPresence.userPresenceType !== 2) {
        // User stopped playing - end the session
        const previousGameId = gameHistoryData.currentGame;
        if (previousGameId && gameHistoryData.gameStartTime) {
          const sessionDuration = currentTime - gameHistoryData.gameStartTime;

          // Ensure game entry exists
          if (!gameHistoryData.games[previousGameId]) {
            gameHistoryData.games[previousGameId] = {
              totalTime: 0,
              name: gameHistoryData.currentGameName || "Unknown Game",
              dailyTime: 0,
              lastPlayed: currentTime,
              sessions: [],
            };
          }

          const game = gameHistoryData.games[previousGameId];

          // Add session record
          const session = {
            startTime: gameHistoryData.gameStartTime,
            endTime: currentTime,
            duration: sessionDuration,
            timestamp: currentTime,
          };

          game.sessions.push(session);

          // Limit session history
          if (game.sessions.length > MAX_SESSIONS_PER_GAME) {
            game.sessions = game.sessions
              .sort((a, b) => b.timestamp - a.timestamp)
              .slice(0, MAX_SESSIONS_PER_GAME);
          }

          // Update lastPlayed timestamp
          game.lastPlayed = currentTime;

          // Update lastOnline with game details
          this.trackerData[userId].lastOnline = {
            timestamp: currentTime,
            gameId: previousGameId,
            gameName: gameHistoryData.currentGameName,
            sessionDuration: sessionDuration,
            presenceType: oldPresenceType,
          };
        }

        // Clear current game tracking
        gameHistoryData.currentGame = null;
        gameHistoryData.gameStartTime = null;
        gameHistoryData.currentGameName = null;
      }

      // Update current game tracking
      if (newPresence.userPresenceType === 2 && newPresence.rootPlaceId) {
        // User is playing a game

        // Only continue existing session if:
        // 1. User was already playing (oldPresenceType === 2)
        // 2. Same game (currentGame == rootPlaceId)
        // 3. Session is active (gameStartTime is set)
        // Otherwise, start a new session (user came back after going offline, or switched games)
        const isContinuingSession =
          oldPresenceType === 2 &&
          gameHistoryData.currentGame == newPresence.rootPlaceId &&
          gameHistoryData.gameStartTime !== null;

        if (isContinuingSession) {
          // User is still playing the same game continuously (never went offline)
          const game = gameHistoryData.games[newPresence.rootPlaceId];
          if (game) {
            game.totalTime += timeSpent;
            // Only add time spent in the current day to dailyTime
            // This handles sessions that span multiple days correctly
            const timeInCurrentDay = this.getTimeInCurrentDay(
              lastUpdate,
              currentTime,
              today,
            );
            game.dailyTime += timeInCurrentDay;
          }
        } else {
          // Start a new session (either different game, or user came back after going offline)
          // End previous game session if exists
          if (gameHistoryData.currentGame && gameHistoryData.gameStartTime) {
            const previousGameId = gameHistoryData.currentGame;
            if (gameHistoryData.games[previousGameId]) {
              const sessionDuration =
                currentTime - gameHistoryData.gameStartTime;
              const game = gameHistoryData.games[previousGameId];

              const session = {
                startTime: gameHistoryData.gameStartTime,
                endTime: currentTime,
                duration: sessionDuration,
                timestamp: currentTime,
              };

              game.sessions.push(session);
              game.lastPlayed = currentTime;

              // Limit session history
              if (game.sessions.length > MAX_SESSIONS_PER_GAME) {
                game.sessions = game.sessions
                  .sort((a, b) => b.timestamp - a.timestamp)
                  .slice(0, MAX_SESSIONS_PER_GAME);
              }
            }
          }

          // Start new game session
          gameHistoryData.currentGame = newPresence.rootPlaceId;
          gameHistoryData.currentGameName = newPresence.lastLocation;
          gameHistoryData.gameStartTime = currentTime;

          // Initialize new game entry if needed
          if (!gameHistoryData.games[newPresence.rootPlaceId]) {
            gameHistoryData.games[newPresence.rootPlaceId] = {
              totalTime: 0,
              name: newPresence.lastLocation || "Unknown Game",
              dailyTime: 0,
              lastPlayed: currentTime,
              sessions: [],
            };
            // Cap distinct games per user (evict least-recently-played) so the
            // map — and the chrome.storage blob it is serialized into every
            // cycle — cannot grow without bound for users who play many games.
            this.pruneGames(gameHistoryData.games, MAX_GAMES_PER_USER);
          } else {
            // Update lastPlayed for existing game
            gameHistoryData.games[newPresence.rootPlaceId].lastPlayed =
              currentTime;
          }
        }
      }

      // Update lastOnline when user is online (even if not playing a game)
      if (newPresence.userPresenceType > 0) {
        const lastOnline = this.trackerData[userId].lastOnline;
        if (!lastOnline.timestamp || currentTime > lastOnline.timestamp) {
          this.trackerData[userId].lastOnline = {
            timestamp: currentTime,
            gameId:
              newPresence.userPresenceType === 2
                ? newPresence.rootPlaceId
                : null,
            gameName:
              newPresence.userPresenceType === 2
                ? newPresence.lastLocation
                : null,
            sessionDuration: 0,
            presenceType: newPresence.userPresenceType,
          };
        }
      }

      return gameHistoryData;
    } catch (error) {
      console.error("[TRACKER] FatalError updating game data:", error);
      return gameHistoryData;
    }
  }

  // Keep at most `maxGames` entries in a user's games map, evicting the
  // least-recently-played ones. Mutates the passed object in place.
  pruneGames(games, maxGames) {
    const ids = Object.keys(games);
    if (ids.length <= maxGames) return;

    ids
      .sort((a, b) => (games[b].lastPlayed || 0) - (games[a].lastPlayed || 0))
      .slice(maxGames)
      .forEach((id) => {
        delete games[id];
      });
  }

  updateWebsiteStudioSessions(userId, newPresence, currentTime, timeSpent) {
    const MAX_SESSIONS = 100; // Store more sessions for website/studio since they're less frequent
    const userData = this.trackerData[userId];
    const oldPresenceType = userData.presenceType || 0;
    const newPresenceType = newPresence.userPresenceType;

    // Initialize sessions arrays if they don't exist
    if (!Array.isArray(userData.websiteSessions)) {
      userData.websiteSessions = [];
    }
    if (!Array.isArray(userData.studioSessions)) {
      userData.studioSessions = [];
    }

    // Handle website sessions (presenceType 1)
    if (oldPresenceType === 1 && newPresenceType !== 1) {
      // User stopped being on website - end the session
      if (userData.websiteStartTime) {
        const sessionDuration = currentTime - userData.websiteStartTime;
        const session = {
          startTime: userData.websiteStartTime,
          endTime: currentTime,
          duration: sessionDuration,
          timestamp: currentTime,
        };
        userData.websiteSessions.push(session);

        // Limit session history
        if (userData.websiteSessions.length > MAX_SESSIONS) {
          userData.websiteSessions = userData.websiteSessions
            .sort((a, b) => b.timestamp - a.timestamp)
            .slice(0, MAX_SESSIONS);
        }
        userData.websiteStartTime = null;
      }
    } else if (newPresenceType === 1 && oldPresenceType !== 1) {
      // User started being on website - start new session
      userData.websiteStartTime = currentTime;
    }

    // Handle studio sessions (presenceType 3)
    if (oldPresenceType === 3 && newPresenceType !== 3) {
      // User stopped being in studio - end the session
      if (userData.studioStartTime) {
        const sessionDuration = currentTime - userData.studioStartTime;
        const session = {
          startTime: userData.studioStartTime,
          endTime: currentTime,
          duration: sessionDuration,
          timestamp: currentTime,
        };
        userData.studioSessions.push(session);

        // Limit session history
        if (userData.studioSessions.length > MAX_SESSIONS) {
          userData.studioSessions = userData.studioSessions
            .sort((a, b) => b.timestamp - a.timestamp)
            .slice(0, MAX_SESSIONS);
        }
        userData.studioStartTime = null;
      }
    } else if (newPresenceType === 3 && oldPresenceType !== 3) {
      // User started being in studio - start new session
      userData.studioStartTime = currentTime;
    }
  }

  // Sorting and query utility methods
  getGamesSortedByLastPlayed(userId) {
    if (!this.trackerData[userId] || !this.trackerData[userId].gameHistory) {
      return [];
    }

    const games = this.trackerData[userId].gameHistory.games;
    return Object.entries(games)
      .map(([placeId, game]) => ({
        placeId,
        ...game,
      }))
      .sort((a, b) => (b.lastPlayed || 0) - (a.lastPlayed || 0));
  }

  getGamesSortedByTotalTime(userId) {
    if (!this.trackerData[userId] || !this.trackerData[userId].gameHistory) {
      return [];
    }

    const games = this.trackerData[userId].gameHistory.games;
    return Object.entries(games)
      .map(([placeId, game]) => ({
        placeId,
        ...game,
      }))
      .sort((a, b) => (b.totalTime || 0) - (a.totalTime || 0));
  }

  getGamesSortedByDailyTime(userId) {
    if (!this.trackerData[userId] || !this.trackerData[userId].gameHistory) {
      return [];
    }

    const games = this.trackerData[userId].gameHistory.games;
    return Object.entries(games)
      .map(([placeId, game]) => ({
        placeId,
        ...game,
      }))
      .sort((a, b) => (b.dailyTime || 0) - (a.dailyTime || 0));
  }

  getGamesSortedByName(userId) {
    if (!this.trackerData[userId] || !this.trackerData[userId].gameHistory) {
      return [];
    }

    const games = this.trackerData[userId].gameHistory.games;
    return Object.entries(games)
      .map(([placeId, game]) => ({
        placeId,
        ...game,
      }))
      .sort((a, b) => {
        const nameA = (a.name || "Unknown Game").toLowerCase();
        const nameB = (b.name || "Unknown Game").toLowerCase();
        return nameA.localeCompare(nameB);
      });
  }

  getRecentSessions(userId, limit = 10) {
    if (!this.trackerData[userId] || !this.trackerData[userId].gameHistory) {
      return [];
    }

    const games = this.trackerData[userId].gameHistory.games;
    const allSessions = [];

    for (const [placeId, game] of Object.entries(games)) {
      if (game.sessions && Array.isArray(game.sessions)) {
        for (const session of game.sessions) {
          allSessions.push({
            placeId,
            gameName: game.name,
            ...session,
          });
        }
      }
    }

    return allSessions
      .sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0))
      .slice(0, limit);
  }

  getLastGameInfo(userId) {
    if (!this.trackerData[userId]) {
      return null;
    }

    const lastOnline = this.trackerData[userId].lastOnline;
    if (!lastOnline || !lastOnline.timestamp) {
      return null;
    }

    return {
      timestamp: lastOnline.timestamp,
      gameId: lastOnline.gameId,
      gameName: lastOnline.gameName,
      sessionDuration: lastOnline.sessionDuration,
      presenceType: lastOnline.presenceType,
    };
  }

  async notifyTrackingData() {
    await storageManager.set(TRACKER_STORAGE_KEY, this.trackerData);
    const tabs = await chrome.tabs.query({ url: "*://*.roblox.com/*" });
    if (tabs && Array.isArray(tabs)) {
      tabs.forEach(async (tab) => {
        try {
          await chrome.tabs.sendMessage(tab.id, {
            type: "PRESENCE_TRACKER_UPDATED",
            data: this.trackerData,
          });
        } catch (error) {}
      });
    }
  }
}

const presenceTracker = new PresenceTracker();
export default presenceTracker;
