const UPDATE_ALARM_NAME = "betterblox-extension-update-check";

class ExtensionUpdater {
  constructor() {
    this.CHECK_INTERVAL_MINUTES = 30;
    this.MAX_RETRIES = 3;
    this.retryCount = 0;
  }

  init() {
    // Listen for update availability
    chrome.runtime.onUpdateAvailable.addListener((details) => {
      console.log(`Update available: version ${details.version}`);
      this.performUpdate();
    });

    // Start periodic checks
    this.startUpdateChecks();
  }

  async performUpdate() {
    try {
      // Reload the extension to apply the update
      chrome.runtime.reload();
    } catch (error) {
      console.error("Error during update:", error);
    }
  }

  async checkForUpdates() {
    try {
      // Check if requestUpdateCheck is available (Chrome, Edge, Opera)
      if (typeof chrome.runtime.requestUpdateCheck === "function") {
        const status = await this.requestUpdateCheck();

        switch (status) {
          case "update_available":
            console.log("Update is pending...");
            break;
          case "no_update":
            console.log("Extension is up to date");
            this.retryCount = 0; // Reset retry count on successful check
            break;
          case "throttled":
            console.log("Update check throttled. Backing off...");
            this.handleThrottled();
            break;
          default:
            console.log(`Unknown update status: ${status}`);
        }
      } else {
        // Firefox doesn't support requestUpdateCheck
        console.log("Automatic update checking not supported in this browser");
        this.retryCount = 0; // Reset retry count since we can't actually check
      }
    } catch (error) {
      console.error("Error checking for updates:", error);
      this.handleError();
    }
  }

  requestUpdateCheck() {
    return new Promise((resolve) => {
      try {
        chrome.runtime.requestUpdateCheck((status) => {
          resolve(status);
        });
      } catch (error) {
        console.warn("requestUpdateCheck not supported:", error);
        resolve("no_update"); // Default fallback
      }
    });
  }

  handleThrottled() {
    // Increase check interval temporarily when throttled
    this.retryCount++;
    if (this.retryCount < this.MAX_RETRIES) {
      const backoffMinutes =
        this.CHECK_INTERVAL_MINUTES * Math.pow(2, this.retryCount);
      chrome.alarms.create(UPDATE_ALARM_NAME, {
        delayInMinutes: backoffMinutes,
        periodInMinutes: this.CHECK_INTERVAL_MINUTES,
      });
    }
  }

  handleError() {
    // Implement exponential backoff on errors
    this.retryCount++;
    if (this.retryCount < this.MAX_RETRIES) {
      const backoffMinutes =
        this.CHECK_INTERVAL_MINUTES * Math.pow(2, this.retryCount);
      chrome.alarms.create(UPDATE_ALARM_NAME, {
        delayInMinutes: backoffMinutes,
        periodInMinutes: this.CHECK_INTERVAL_MINUTES,
      });
    }
  }

  startUpdateChecks() {
    this.checkForUpdates();

    // chrome.alarms survives MV3 service-worker unloads; setInterval does not.
    chrome.alarms.create(UPDATE_ALARM_NAME, {
      periodInMinutes: this.CHECK_INTERVAL_MINUTES,
    });
    chrome.alarms.onAlarm.addListener((alarm) => {
      if (
        alarm.name === UPDATE_ALARM_NAME &&
        this.retryCount < this.MAX_RETRIES
      ) {
        this.checkForUpdates();
      }
    });
  }
}

// Create and export the updater instance
const extensionUpdater = new ExtensionUpdater();
export default extensionUpdater;
