import robloxApi from "../../utils/robloxApi/main.js";
import { storageManager } from "../../../betterblox-frontend/core/storageManager.js";
import { browserAPI } from "../../utils/browserAPI.js";

const AUTH_STORAGE_KEY = "betterblox_auth_status";
const AUTH_CHECK_INTERVAL = 30000; // 1 minute

class AuthenticationManager {
  constructor() {
    this.authData = null;
    this.lastAuthCheck = 0; // Timestamp of last auth check
    this.AUTH_RATE_LIMIT = 5000; // 5 seconds minimum between API calls
  }

  async init() {
    console.log("Initializing authentication manager");

    // Load existing auth data from storage
    const stored = await browserAPI.storage.local.get(AUTH_STORAGE_KEY);
    this.authData =
      stored && stored[AUTH_STORAGE_KEY] ? stored[AUTH_STORAGE_KEY] : null;
    try {
      await this.checkAuthStatus();
    } catch (error) {
      console.error("Failed to check authentication status:", error);
    }
    // Start periodic checking
    this.startPeriodicCheck();
  }

  async checkAuthStatus() {
    const now = Date.now();
    const timeSinceLastCheck = now - this.lastAuthCheck;

    // If less than 5 seconds since last check, return cached data
    if (timeSinceLastCheck < this.AUTH_RATE_LIMIT && this.authData) {
      return this.authData.id;
    }

    try {
      const data = await robloxApi.getCurrentUser();
      // Roblox answers 401 when logged out (thrown + handled below), but some
      // edge cases (proxies, partial/expired sessions) reply 200 with id 0.
      // Treat any non-positive / non-integer id as logged-out so we never persist
      // a phantom "user 0" — otherwise callers fire /users/0/... (400) and the
      // extension reports a bogus signed-in state.
      const id = Number(data?.id);
      if (!Number.isInteger(id) || id <= 0) {
        this.authData = null;
        this.lastAuthCheck = now;
        await this.updateStorage();
        return null;
      }
      this.authData = {
        id,
        name: data.name,
        displayName: data.displayName,
        lastChecked: new Date().toISOString(),
      };
      this.lastAuthCheck = now; // Update last check timestamp
      await this.updateStorage();
      return id; // Return the user ID directly
    } catch (error) {
      console.warn("[AUTH] Auth check failed:", error.message);
      this.authData = null;
      this.lastAuthCheck = now; // Update timestamp even on failure
      await this.updateStorage();
      return null;
    }
  }

  async updateStorage() {
    await browserAPI.storage.local.set({ [AUTH_STORAGE_KEY]: this.authData });
    // Dispatch event for other parts of the extension
  }

  async startPeriodicCheck() {
    // Initial check
    try {
      await this.checkAuthStatus();
    } catch (error) {
      console.error("Failed to check authentication status:", error);
    }
    // Set up periodic checking
    browserAPI.alarms.create("authStatusCheck", {
      periodInMinutes: AUTH_CHECK_INTERVAL / 60000,
    });

    browserAPI.alarms.onAlarm.addListener((alarm) => {
      if (alarm.name === "authStatusCheck") {
        this.checkAuthStatus();
      }
    });
  }

  // Helper method to get current auth status
  async getCurrentAuth() {
    const stored = await browserAPI.storage.local.get(AUTH_STORAGE_KEY);
    return stored && stored[AUTH_STORAGE_KEY] ? stored[AUTH_STORAGE_KEY] : null;
  }

  // Helper method to check if user is authenticated
  async isAuthenticated() {
    let auth = await this.getCurrentAuth();
    if (!auth) {
      await this.checkAuthStatus();
      auth = await this.getCurrentAuth();
    }
    return !!auth;
  }
  async getAuthData(forceFresh = false) {
    // Always return the latest auth data, refresh if needed or forced
    if (!this.authData || forceFresh) {
      await this.checkAuthStatus();
    }
    return this.authData;
  }
}

const authManager = new AuthenticationManager();
export default authManager;
