import storageManager from "../../utils/storageManager.js";
import friendsService from "../friends/friendsService.js";
import { browserAPI } from "../../utils/browserAPI.js";

// Note: Raw presence data is no longer stored - it's only kept in memory
// and passed to subscribers (like presenceTracker) which stores processed data
const PRESENCE_CHECK_INTERVAL = 45000; // 15 seconds
const BATCH_SIZE = 100; // Number of users to request at once

class FriendsPresenceManager {
  constructor() {
    this.presenceData = {};
    this.subscribers = [];
    this.lastServerSend = 0; // Track last time we sent data to server
    this.trackingListMigrated = false;
  }

  addSubscriber(subscriber) {
    if (typeof subscriber.handlePresenceUpdate === "function") {
      console.log("[PRESENCE] Adding subscriber", subscriber.constructor.name);
      this.subscribers.push(subscriber);
      return true;
    }
    console.warn(
      "[PRESENCE] Attempted to add invalid subscriber - missing handlePresenceUpdate method",
    );
    return false;
  }

  async getAllUserIds() {
    const [friendIds, trackingData, currentUser, autoJoinList] =
      await Promise.all([
        friendsService.getFriendIds(), // Use the friends service instead of direct storage access
        this.getTrackingList(),
        storageManager.get("betterblox_auth_status", {
          id: null,
          name: null,
          displayName: null,
          lastChecked: null,
        }),
        storageManager.get("autoJoin", []),
      ]);

    // Combine and deduplicate friend IDs and tracked IDs
    // Ensure all values are arrays to prevent forEach errors
    const safeFriendIds = Array.isArray(friendIds) ? friendIds : [];
    const safeTrackingData = Array.isArray(trackingData) ? trackingData : [];
    const safeAutoJoinList = Array.isArray(autoJoinList) ? autoJoinList : [];
    const uniqueIds = new Set([
      ...safeFriendIds,
      ...safeTrackingData,
      ...safeAutoJoinList,
    ]);
    if (currentUser?.id) {
      uniqueIds.add(currentUser.id);
    }
    return Array.from(uniqueIds);
  }

  async migrateTrackingListV1toV2() {
    if (this.trackingListMigrated) return;
    this.trackingListMigrated = true;

    const existing = await storageManager.get("betterblox_tracking_list_v2", []);
    if (existing.length > 0) return; // already on v2

    const oldData = await storageManager.get("betterblox_tracking_list", null);
    if (!oldData?.trackIDs) return;

    await storageManager.set("betterblox_tracking_list_v2", oldData.trackIDs);
    await browserAPI.storage.local.remove("betterblox_tracking_list");
    console.log("[PRESENCE] Migrated betterblox_tracking_list to v2 format");
  }

  async getTrackingList() {
    return await storageManager.get("betterblox_tracking_list_v2", []);
  }

  async initialize() {
    console.log("[SERVICE] Initializing presence manager");
    // Presence data is kept in memory only - no need to load from storage
    // The processed tracking data is stored in betterblox_presence_tracker_v2
    this.presenceData = {};
    await this.migrateTrackingListV1toV2();
    // Start periodic presence checks
    this.startPeriodicCheck();
  }

  async updateUserPresence(userId, newPresence) {
    this.presenceData[userId] = {
      ...newPresence,
    };
  }

  async notifyPresenceChanged() {
    // No longer storing raw presence data - it's ephemeral and only needed in memory
    // The processed tracking data is stored by presenceTracker in betterblox_presence_tracker_v2

    // Notify direct subscribers (like presenceTracker)
    // The tracker will process this data and send PRESENCE_TRACKER_UPDATED to frontend
    if (this.subscribers && this.subscribers.length > 0) {
      console.log(
        "[PRESENCE] Notifying",
        this.subscribers.length,
        "direct subscribers",
      );
      for (const subscriber of this.subscribers) {
        try {
          subscriber.handlePresenceUpdate(this.presenceData);
        } catch (error) {
          console.error("[PRESENCE] Error notifying subscriber:", error);
        }
      }
    }

    // No longer sending FRIENDS_PRESENCE_UPDATED message - frontend uses PRESENCE_TRACKER_UPDATED instead
  }

  async updatePresencesLoop() {
    try {
      const userIds = await this.getAllUserIds();
      const presences = (await getPresenceBatch(userIds)) || [];
      for (const presence of presences) {
        await this.updateUserPresence(presence.userId, presence);
      }
      if (presences.length > 0) {
        await this.notifyPresenceChanged();

        // Server communication is now handled by OptimizedServerSync service
        // which subscribes to presence updates independently
      }
    } catch (error) {
      console.error("[PRESENCE] Failed to updatePresencesLoop:", error);
    }
  }

  // Server communication moved to OptimizedServerSync service

  startPeriodicCheck() {
    this.updatePresencesLoop();

    chrome.alarms.create("friendsPresenceCheck", {
      periodInMinutes: PRESENCE_CHECK_INTERVAL / 60000,
    });

    chrome.alarms.onAlarm.addListener((alarm) => {
      if (alarm.name === "friendsPresenceCheck") {
        this.updatePresencesLoop();
      }
    });
  }
}

async function getPresenceBatch(userIds) {
  try {
    if (userIds.length === 0) {
      console.log("[PRESENCE] No users to check presence for");
      return [];
    }
    let presences = [];

    // Process users in batches
    for (let i = 0; i < userIds.length; i += BATCH_SIZE) {
      const currentBatch = userIds.slice(i, i + BATCH_SIZE);
      const presencesResponse = await getUsersPresence(currentBatch);
      if (presencesResponse.length > 0) {
        presences.push(...presencesResponse);
      }
    }
    return presences;
  } catch (error) {
    console.error("[PRESENCE] Failed to update presences:", error);
    return [];
  }
}

async function getUsersPresence(userIds) {
  if (userIds.length === 0) {
    console.log("[PRESENCE] No users to check presence for");
    return [];
  }

  const response = await fetch(
    `https://presence.roblox.com/v1/presence/users`,
    {
      method: "POST",
      body: JSON.stringify({ userIds }),
    },
  );

  if (!response.ok) {
    console.error(
      "[PRESENCE] Failed to fetch presence batch:",
      response.statusText,
    );
    return [];
  }

  const data = await response.json();
  return data.userPresences || [];
}

const friendsPresenceManager = new FriendsPresenceManager();
export default friendsPresenceManager;
