export function parseRetryAfterMs(response, defaultMs) {
  const raw = response.headers.get("retry-after") ?? response.headers.get("Retry-After");
  if (raw == null || raw === "") return defaultMs;
  const trimmed = String(raw).trim();
  if (/^\d+$/.test(trimmed)) {
    return Number.parseInt(trimmed, 10) * 1000;
  }
  const httpDate = Date.parse(trimmed);
  if (!Number.isNaN(httpDate)) {
    return Math.max(0, httpDate - Date.now());
  }
  return defaultMs;
}
