import robloxApi from "../../utils/robloxApi/main.js";
import { browserAPI } from "../../utils/browserAPI.js";

const CHECK_INTERVAL_MINUTES = 2;
const FULL_REFRESH_INTERVAL = 5; // force full friend-list fetch every N checks (catches add+remove same cycle)
const STORAGE_KEY = "betterblox_friend_tracking";
const HISTORY_STORAGE_KEY = "betterblox_friend_tracking_history";
const MAX_HISTORY_PER_USER = 100;
const ALARM_PREFIX = "friendTracking_";

const storageAPI = browserAPI.storage.local;

// ── Storage helpers (MV3 promises) ──────────────────────────────────

async function getStore(key) {
  const result = await storageAPI.get([key]);
  return result[key] || {};
}

function setStore(key, value) {
  return storageAPI.set({ [key]: value });
}

function isFriendsPrivateError(err) {
  return err?.message?.includes("403");
}

// ── Service ─────────────────────────────────────────────────────────

class FriendTrackingService {
  constructor() {
    this.activeAlarms = new Map();
    this.setupAlarmListener();
  }

  setupAlarmListener() {
    chrome.alarms.onAlarm.addListener((alarm) => {
      if (alarm.name?.startsWith(ALARM_PREFIX)) {
        this.checkFriendChanges(alarm.name.slice(ALARM_PREFIX.length));
      }
    });
  }

  // ── Public API ────────────────────────────────────────────────────

  async initializeTracking(userId) {
    const uid = String(userId);

    let currentCount;
    try {
      const countRes = await robloxApi.getFriendsCount(uid);
      currentCount = countRes.count;
    } catch (err) {
      if (isFriendsPrivateError(err)) {
        return { success: false, error: "FRIENDS_PRIVATE" };
      }
      throw err;
    }

    const tracking = await getStore(STORAGE_KEY);
    const existing = tracking[uid];

    if (existing?.friendIds?.length && existing.count === currentCount) {
      existing.lastChecked = Date.now();
      existing.checksSinceFullRefresh = 0;
      existing.isTracking = true;
      await setStore(STORAGE_KEY, tracking);
      this.startAlarm(uid);
      return { success: true, count: currentCount, friendCount: existing.friendIds.length };
    }

    let friends;
    try {
      friends = await robloxApi.getAllFriends(uid);
    } catch (err) {
      if (isFriendsPrivateError(err)) {
        return { success: false, error: "FRIENDS_PRIVATE" };
      }
      throw err;
    }

    const friendIds = friends.map((f) => f.id);

    tracking[uid] = {
      count: currentCount,
      friendIds,
      lastChecked: Date.now(),
      checksSinceFullRefresh: 0,
      isTracking: true,
    };

    await setStore(STORAGE_KEY, tracking);
    this.startAlarm(uid);

    return { success: true, count: currentCount, friendCount: friendIds.length };
  }

  async stopTracking(userId) {
    const uid = String(userId);
    this.clearAlarm(uid);

    const tracking = await getStore(STORAGE_KEY);
    if (tracking[uid]) {
      delete tracking[uid];
      await setStore(STORAGE_KEY, tracking);
    }

    return { success: true };
  }

  async isTracking(userId) {
    const tracking = await getStore(STORAGE_KEY);
    return tracking[String(userId)]?.isTracking === true;
  }

  async getTrackingDataForUser(userId) {
    const tracking = await getStore(STORAGE_KEY);
    return tracking[String(userId)] || null;
  }

  async getHistory(userId) {
    const history = await getStore(HISTORY_STORAGE_KEY);
    return history[String(userId)] || [];
  }

  // ── Alarm management ──────────────────────────────────────────────

  startAlarm(uid) {
    this.clearAlarm(uid);
    const name = `${ALARM_PREFIX}${uid}`;
    chrome.alarms.create(name, { periodInMinutes: CHECK_INTERVAL_MINUTES });
    this.activeAlarms.set(uid, name);
  }

  clearAlarm(uid) {
    const name = this.activeAlarms.get(uid);
    if (name) {
      chrome.alarms.clear(name);
      this.activeAlarms.delete(uid);
    }
  }

  // ── Core diffing logic ────────────────────────────────────────────

  async checkFriendChanges(uid) {
    try {
      const tracking = await getStore(STORAGE_KEY);
      const userData = tracking[uid];

      if (!userData?.isTracking) {
        this.clearAlarm(uid);
        return;
      }

      const countRes = await robloxApi.getFriendsCount(uid);
      const currentCount = countRes.count;
      const checksSoFar = (userData.checksSinceFullRefresh || 0) + 1;
      const forceFullRefresh = checksSoFar >= FULL_REFRESH_INTERVAL;

      if (currentCount === userData.count && !forceFullRefresh) {
        userData.lastChecked = Date.now();
        userData.checksSinceFullRefresh = checksSoFar;
        await setStore(STORAGE_KEY, tracking);
        return;
      }

      const friends = await robloxApi.getAllFriends(uid);
      const currentIds = friends.map((f) => f.id);

      const prevSet = new Set(userData.friendIds || []);
      const currSet = new Set(currentIds);

      const added = currentIds.filter((id) => !prevSet.has(id));
      const removed = (userData.friendIds || []).filter((id) => !currSet.has(id));

      userData.count = currentCount;
      userData.friendIds = currentIds;
      userData.lastChecked = Date.now();
      userData.checksSinceFullRefresh = 0;
      await setStore(STORAGE_KEY, tracking);

      if (added.length === 0 && removed.length === 0) return;

      await this.appendHistory(uid, {
        timestamp: Date.now(),
        previousCount: prevSet.size,
        currentCount,
        added,
        removed,
      });

      chrome.runtime
        .sendMessage({
          type: "FRIEND_TRACKING_CHANGED",
          userId: uid,
          data: { added, removed, currentCount },
        })
        .catch(() => {});
    } catch (error) {
      if (isFriendsPrivateError(error)) {
        console.warn(`[FriendTracking] Friends list for ${uid} is now private, stopping.`);
        this.clearAlarm(uid);
        return;
      }
      console.error(`[FriendTracking] Check failed for ${uid}:`, error);
    }
  }

  // ── History ───────────────────────────────────────────────────────

  async appendHistory(uid, entry) {
    const history = await getStore(HISTORY_STORAGE_KEY);
    const list = history[uid] || [];
    list.unshift(entry);
    history[uid] = list.length > MAX_HISTORY_PER_USER
      ? list.slice(0, MAX_HISTORY_PER_USER)
      : list;
    await setStore(HISTORY_STORAGE_KEY, history);
  }

  // ── Startup ───────────────────────────────────────────────────────

  async initializeAllTrackings() {
    const tracking = await getStore(STORAGE_KEY);
    for (const uid of Object.keys(tracking)) {
      if (tracking[uid].isTracking) {
        this.startAlarm(uid);
      }
    }
  }
}

const friendTrackingService = new FriendTrackingService();
friendTrackingService.initializeAllTrackings();

export default friendTrackingService;
