import robloxApi from "../../utils/robloxApi/main.js";
import storageManager from "../../utils/storageManager.js";
import getAuthStatus from "../authentication/getAuthStatus.js";
import { notifyRobloxTabs } from "../../utils/notifyRobloxTabs.js";

const FRIENDS_STORAGE_KEY = "betterblox_friends_list"; // Will be used with storageManager prefix // DO NOT CHANGE THIS
const FRIENDS_CHECK_INTERVAL = 60000; // 1 minute

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

class FriendsService {
  constructor() {
    this.friendsData = {}; // Will store per-user friend lists: { userId: { friendIds: [], lastUpdated: "", count: 0 } }
    this.currentUserId = null;
    this.subscribers = [];
    this.isInitialized = false;
  }

  /**
   * Add a subscriber to receive friends list updates
   * @param {Object} subscriber - Object with handleFriendsUpdate method
   * @returns {boolean} - Success status
   */
  addSubscriber(subscriber) {
    if (typeof subscriber.handleFriendsUpdate === "function") {
      console.log("[FRIENDS] Adding subscriber", subscriber.constructor.name);
      this.subscribers.push(subscriber);
      return true;
    }
    console.warn("[FRIENDS] Attempted to add invalid subscriber - missing handleFriendsUpdate method");
    return false;
  }

  /**
   * Remove a subscriber from friends list updates
   * @param {Object} subscriber - Subscriber to remove
   * @returns {boolean} - Success status
   */
  removeSubscriber(subscriber) {
    const index = this.subscribers.indexOf(subscriber);
    if (index > -1) {
      this.subscribers.splice(index, 1);
      console.log("[FRIENDS] Removed subscriber", subscriber.constructor.name);
      return true;
    }
    return false;
  }

  /**
   * Initialize the friends service
   */
  async initialize() {
    if (this.isInitialized) {
      console.log("[FRIENDS] Service already initialized");
      return;
    }

    console.log("[FRIENDS] Initializing friends service");

    try {
      // Load all friends data from storage using storageManager
      this.friendsData = await storageManager.get(FRIENDS_STORAGE_KEY, {});

      // Get current user ID if available
      await this.updateCurrentUser();

      console.log(`[FRIENDS] Loaded friends data for ${Object.keys(this.friendsData).length} users`);
      if (this.currentUserId) {
        const currentUserFriends = this.friendsData[this.currentUserId];
        console.log(`[FRIENDS] Current user ${this.currentUserId} has ${currentUserFriends?.count || 0} friends`);
      }

      this.isInitialized = true;
      await this.startPeriodicCheck();
    } catch (error) {
      console.error("[FRIENDS] Failed to initialize:", error);
    }
  }

  /**
   * Update current user ID and handle account switching
   */
  async updateCurrentUser() {
    try {
      const authData = await getAuthStatus.getAuthData(true);
      // Validate a positive id — "0" (logged-out sentinel) is a truthy string and
      // would otherwise be treated as a real account.
      const validId = Number(authData?.id);
      const newUserId =
        Number.isInteger(validId) && validId > 0 ? String(validId) : null;

      if (newUserId !== this.currentUserId) {
        const previousUserId = this.currentUserId;
        this.currentUserId = newUserId;

        if (previousUserId && newUserId) {
          console.log(`[FRIENDS] Account switched from ${previousUserId} to ${newUserId}`);
        } else if (newUserId) {
          console.log(`[FRIENDS] User logged in: ${newUserId}`);
        } else {
          console.log(`[FRIENDS] User logged out`);
        }

        // Notify subscribers about the account change
        await this.notifyFriendsChanged(true); // true = account switched
      }

      return newUserId;
    } catch (error) {
      console.error("[FRIENDS] Failed to update current user:", error);
      return null;
    }
  }

  /**
   * Update the friends list from Roblox API
   */
  async updateFriendsList() {
    try {
      // Always get fresh user ID directly from API, don't rely on cached data.
      // Validate it's a positive id — "0" (logged-out sentinel) is a truthy string
      // and would otherwise slip past the guard and hit /users/0/friends/find.
      const freshAuthId = Number((await getAuthStatus.getAuthData(true))?.id);
      const freshUserId =
        Number.isInteger(freshAuthId) && freshAuthId > 0 ? String(freshAuthId) : null;

      if (!freshUserId) {
        console.log("[FRIENDS] User not authenticated, skipping friends update");
        return;
      }

      // Check if user switched accounts
      if (freshUserId !== this.currentUserId) {
        const previousUserId = this.currentUserId;
        this.currentUserId = freshUserId;

        if (previousUserId && freshUserId) {
          console.log(`[FRIENDS] Account switched from ${previousUserId} to ${freshUserId}`);
          await this.notifyFriendsChanged(true); // true = account switched
        } else if (freshUserId) {
          console.log(`[FRIENDS] User logged in: ${freshUserId}`);
          await this.notifyFriendsChanged(true); // true = account switched
        }
      }

      const userId = freshUserId;

      console.log(`[FRIENDS] Fetching friends for user: ${userId}`);
      const friends = await robloxApi.getAllFriends(parseInt(userId));
      const friendIds = friends
        .map((friend) => friend.id)
        .filter((id) => {
          const numId = parseInt(id);
          return numId > 0 && !isNaN(numId);
        });

      // Get previous friends for this user (not global)
      const previousUserData = this.friendsData[userId];
      const previousFriendIds = previousUserData?.friendIds || [];

      // Update friends data for this specific user
      this.friendsData[userId] = {
        lastUpdated: new Date().toISOString(),
        friendIds: friendIds,
        count: friendIds.length,
      };

      // Save to storage and notify subscribers
      await this.notifyFriendsChanged();

      console.log(`[FRIENDS] Updated friends list for user ${userId}: ${friendIds.length} friends found`);

      // Log changes if any (only for debugging)
      const added = friendIds.filter((id) => !previousFriendIds.includes(id));
      const removed = previousFriendIds.filter((id) => !friendIds.includes(id));

      if (added.length > 0) {
        console.log(`[FRIENDS] New friends added: ${added.length}`);
      }
      if (removed.length > 0) {
        console.log(`[FRIENDS] Friends removed: ${removed.length}`);
      }
    } catch (error) {
      console.error("[FRIENDS] Failed to update friends list:", error);
    }
  }

  /**
   * Notify all subscribers and update storage when friends list changes
   * @param {boolean} accountSwitched - Whether this notification is due to account switching
   */
  async notifyFriendsChanged(accountSwitched = false) {
    try {
      // Save all friends data to storage using storageManager
      await storageManager.set(FRIENDS_STORAGE_KEY, this.friendsData);

      // Get current user's friends data for notifications
      const currentUserFriends = this.getCurrentUserFriends();

      // Notify direct subscribers
      if (this.subscribers.length > 0) {
        console.log(`[FRIENDS] Notifying ${this.subscribers.length} direct subscribers`);
        for (const subscriber of this.subscribers) {
          try {
            await subscriber.handleFriendsUpdate(currentUserFriends, {
              accountSwitched,
              currentUserId: this.currentUserId,
              allUsersData: this.friendsData,
            });
          } catch (error) {
            console.error("[FRIENDS] Error notifying subscriber:", error);
          }
        }
      }

      // Notify content scripts in Roblox tabs
      await notifyRobloxTabs("FRIENDS_LIST_UPDATED", currentUserFriends, {
        accountSwitched,
        currentUserId: this.currentUserId,
      });
    } catch (error) {
      console.error("[FRIENDS] Failed to notify friends changed:", error);
    }
  }

  /**
   * Start periodic friends list checking
   */
  async startPeriodicCheck() {
    // Initial update
    await this.updateFriendsList();

    // Set up periodic alarm
    chrome.alarms.create("friendsListCheck", {
      periodInMinutes: FRIENDS_CHECK_INTERVAL / 60000,
    });

    // Listen for alarm
    chrome.alarms.onAlarm.addListener((alarm) => {
      if (alarm.name === "friendsListCheck") {
        this.updateFriendsList();
      }
    });

    // Retry until the current user has friends data, but unawaited and
    // bounded: awaiting this loop blocked the whole background init chain
    // (and with it every message handler) for as long as the friends API
    // kept failing.
    void (async () => {
      const MAX_RETRIES = 30;
      for (
        let attempt = 0;
        attempt < MAX_RETRIES && this.currentUserId && !this.getCurrentUserFriends();
        attempt++
      ) {
        console.log("[FRIENDS] No friends data found for current user, waiting 10 seconds before retrying");
        await delay(10000);
        await this.updateFriendsList();
      }
    })();
  }

  /**
   * Get current user's friends data
   * @returns {Object|null} Current user's friends data object
   */
  getCurrentUserFriends() {
    if (!this.currentUserId) {
      return null;
    }
    return this.friendsData[this.currentUserId] || null;
  }

  /**
   * Get friends data for a specific user
   * @param {string} userId - User ID to get friends for
   * @returns {Object|null} Friends data for the specified user
   */
  getUserFriends(userId) {
    return this.friendsData[userId] || null;
  }

  /**
   * Get current friends list (legacy compatibility)
   * @returns {Object|null} Current user's friends list object
   */
  getFriendsList() {
    return this.getCurrentUserFriends();
  }

  /**
   * Get friend IDs array for current user
   * @returns {Array<number>} Array of friend IDs
   */
  async getFriendIds() {
    const currentUserFriends = this.getCurrentUserFriends();
    if (currentUserFriends?.friendIds) {
      return currentUserFriends.friendIds;
    }

    // Fallback to storage if not in memory
    if (this.currentUserId) {
      const stored = await storageManager.get(FRIENDS_STORAGE_KEY, {});
      return stored[this.currentUserId]?.friendIds || [];
    }

    return [];
  }

  /**
   * Get friend IDs for a specific user
   * @param {string} userId - User ID to get friend IDs for
   * @returns {Array<number>} Array of friend IDs
   */
  async getFriendIdsForUser(userId) {
    const userFriends = this.getUserFriends(userId);
    if (userFriends?.friendIds) {
      return userFriends.friendIds;
    }

    // Fallback to storage
    const stored = await storageManager.get(FRIENDS_STORAGE_KEY, {});
    return stored[userId]?.friendIds || [];
  }

  /**
   * Check if a user is a friend of the current user
   * @param {number} userId - User ID to check
   * @returns {boolean} Whether the user is a friend
   */
  async isFriend(userId) {
    const friendIds = await this.getFriendIds();
    return friendIds.includes(parseInt(userId));
  }

  /**
   * Check if a user is a friend of a specific user
   * @param {number} friendId - Friend ID to check
   * @param {string} userId - User ID to check against
   * @returns {boolean} Whether the user is a friend
   */
  async isFriendOfUser(friendId, userId) {
    const friendIds = await this.getFriendIdsForUser(userId);
    return friendIds.includes(parseInt(friendId));
  }

  /**
   * Get friends count for current user
   * @returns {number} Number of friends
   */
  async getFriendsCount() {
    const friendIds = await this.getFriendIds();
    return friendIds.length;
  }

  /**
   * Get friends count for a specific user
   * @param {string} userId - User ID to get friends count for
   * @returns {number} Number of friends
   */
  async getFriendsCountForUser(userId) {
    const friendIds = await this.getFriendIdsForUser(userId);
    return friendIds.length;
  }

  /**
   * Force refresh friends list for current user
   */
  async refreshFriendsList() {
    console.log("[FRIENDS] Manual refresh requested");
    await this.updateFriendsList();
  }

  /**
   * Get all users data (for debugging/admin purposes)
   * @returns {Object} All users friends data
   */
  getAllUsersData() {
    return this.friendsData;
  }

  /**
   * Get current user ID
   * @returns {string|null} Current user ID
   */
  getCurrentUserId() {
    return this.currentUserId;
  }
}

// Create and export the service instance
const friendsService = new FriendsService();
export default friendsService;
