import storageManager from "../../utils/storageManager.js";
import getAuthToken from "../../scripts/oauth/getAuthToken.js";
import { API_BASE_URL } from "../../constants.js";
import {
  emptyHistory,
  recordChunk,
  recordSessionMeta,
  buildDashboard,
} from "./playtimeHistory.js";

/**
 * Playtime XP awarder.
 *
 * Subscribes to the presence service (same channel as presenceTracker) and
 * watches the LOGGED-IN user's own presence — already included in the polled
 * batch via FriendsPresenceManager.getAllUserIds() (currentUser.id). While the
 * user is in a game (userPresenceType === 2) we accrue real elapsed time
 * locally, capped at 120s per poll (same idiom as presenceTracker) so an asleep
 * service worker can never inflate playtime. Accrued time is flushed to the
 * server in fixed 5-minute chunks.
 *
 * Dedup (the hard requirement): every chunk is keyed (sessionId, chunkIndex) and
 * the server dedups via a per-user cursor. We additionally persist the monotonic
 * lastFlushedChunkIndex + accruedMs to chrome.storage, so if the MV3 service
 * worker is killed and restarted mid-session we resume from where we left off
 * and never re-send a chunk; even if we did, the server returns 200 with
 * alreadyAwarded:true and awards nothing (and we skip re-recording it into local
 * history). DB load stays low: one request per ~5 minutes of play, not per poll.
 */

const SESSION_KEY = "playtime_xp_session"; // -> betterblox_playtime_xp_session
const HISTORY_KEY = "playtime_history"; // -> betterblox_playtime_history (local dashboard data)
const CHUNK_MS = 5 * 60 * 1000; // 5-minute chunk
const MAX_TICK_MS = 120000; // cap credited per poll (anti-idle / anti-sleep)
const NEW_SESSION_GAP_MS = MAX_TICK_MS * 2; // gap that splits into a new session
const MIN_PARTIAL_MINUTES = 1; // don't bother flushing sub-minute tails
const XP_PER_MINUTE = 1; // for the local "earned so far" estimate only
const PRESENCE_GAME = 2; // Roblox presenceType: in-game

class PlaytimeXpService {
  constructor() {
    this.name = "PlaytimeXpService"; // for presence-subscriber logging
    this.selfId = null;
    this.state = null; // persisted session (mirror of SESSION_KEY)
    this.history = null; // local dashboard history (mirror of HISTORY_KEY)
    this.loaded = false;
    this.flushing = false;
    this.accessToken = null;
  }

  async init() {
    // Restore an in-progress session after a service-worker restart.
    this.state = await storageManager.get(SESSION_KEY, null);
    this.history = (await storageManager.get(HISTORY_KEY, null)) || emptyHistory();
    this.loaded = true;
  }

  async persistHistory() {
    if (this.history) await storageManager.set(HISTORY_KEY, this.history);
  }

  async getSelfId() {
    if (this.selfId) return this.selfId;
    const auth = await storageManager.get("betterblox_auth_status", { id: null });
    this.selfId = auth && auth.id ? auth.id : null;
    return this.selfId;
  }

  /** Presence-subscriber entrypoint (invoked ~every 45s, not awaited). */
  async handlePresenceUpdate(presenceData) {
    try {
      if (!this.loaded) await this.init();
      const selfId = await this.getSelfId();
      if (!selfId) return;

      const self =
        presenceData[selfId] ||
        presenceData[String(selfId)] ||
        presenceData[Number(selfId)];
      const now = Date.now();

      // If the batch didn't return self at all this poll, do nothing — never end
      // a session on missing data (the presence API can transiently omit a user).
      if (!self) return;

      const inGame = self.userPresenceType === PRESENCE_GAME;
      if (inGame) {
        await this.onInGame(selfId, self, now);
      } else if (this.state) {
        // Self is online but not in a game → clean game-close.
        await this.onGameClosed(now);
      }
    } catch (error) {
      console.error("[PLAYTIME] handlePresenceUpdate error:", error);
    }
  }

  sessionIdFor(selfId, anchor, startedAt) {
    // startedAt (persisted) makes the id stable across SW restarts and unique
    // across sessions; anchor ties it to the game instance/place.
    return `${selfId}:${anchor}:${startedAt}`;
  }

  async onInGame(selfId, self, now) {
    let state = this.state;
    const anchor = String(self.gameId || self.rootPlaceId || self.placeId || "x");

    const isNewSession =
      !state ||
      state.anchor !== anchor ||
      now - (state.lastTickAt || 0) > NEW_SESSION_GAP_MS;

    if (isNewSession) {
      // Close out the previous session (flush its tail) before starting fresh.
      if (state) await this.flush(true);
      const startedAt = now;
      state = {
        sessionId: this.sessionIdFor(selfId, anchor, startedAt),
        anchor,
        userId: selfId,
        placeId: self.rootPlaceId || self.placeId || null,
        gameId: self.gameId || null,
        gameName: self.lastLocation || null,
        startedAt,
        lastTickAt: now,
        accruedMs: 0,
        lastFlushedChunkIndex: -1,
      };
      this.state = state;
    } else {
      const delta = Math.min(now - state.lastTickAt, MAX_TICK_MS);
      if (delta > 0) state.accruedMs += delta;
      state.lastTickAt = now;
      state.placeId = self.rootPlaceId || self.placeId || state.placeId;
      state.gameName = self.lastLocation || state.gameName;
    }

    await this.persist();
    await this.flush(false); // only complete chunks while still playing
  }

  async onGameClosed(now) {
    const state = this.state;
    if (!state) return;

    const delta = Math.min(now - state.lastTickAt, MAX_TICK_MS);
    if (delta > 0) {
      state.accruedMs += delta;
      state.lastTickAt = now;
    }
    await this.flush(true); // include the final sub-5-minute tail

    const summary = {
      sessionId: state.sessionId,
      placeId: state.placeId,
      gameName: state.gameName,
      startedAt: state.startedAt,
      durationMs: state.accruedMs,
      xpEarned: Math.floor((state.accruedMs / 60000) * XP_PER_MINUTE),
    };
    // Append the finished session to the local dashboard history (recent list +
    // per-game session count). Minutes/XP were already credited per chunk above.
    if (this.history) {
      recordSessionMeta(this.history, {
        sessionId: state.sessionId,
        placeId: state.placeId,
        gameName: state.gameName,
        minutes: Math.round(state.accruedMs / 60000),
        xp: summary.xpEarned,
        start: state.startedAt,
        end: now,
      });
      await this.persistHistory();
    }
    await this.clear();
    await this.broadcastSessionComplete(summary);
  }

  /** Local dashboard history projected for /playtime (GET_PLAYTIME_HISTORY). */
  async getHistory() {
    if (!this.loaded) await this.init();
    return buildDashboard(this.history || emptyHistory());
  }

  /** Flush due chunks. includePartial also sends the final sub-5-minute tail. */
  async flush(includePartial) {
    if (this.flushing || !this.state) return;
    this.flushing = true;
    try {
      const state = this.state;
      const completeChunks = Math.floor(state.accruedMs / CHUNK_MS);
      // During play: only whole 5-minute chunks. On close: also the final
      // partial tail — but never a zero-length chunk when accruedMs lands
      // exactly on a 5-minute boundary (that would advance the index for an
      // empty chunk and skip a real one).
      let lastIndex;
      if (includePartial) {
        lastIndex = state.accruedMs % CHUNK_MS === 0 ? completeChunks - 1 : completeChunks;
      } else {
        lastIndex = completeChunks - 1;
      }

      for (let idx = state.lastFlushedChunkIndex + 1; idx <= lastIndex; idx++) {
        const chunkStart = idx * CHUNK_MS;
        const chunkEnd = Math.min((idx + 1) * CHUNK_MS, state.accruedMs);
        const minutes = (chunkEnd - chunkStart) / 60000;

        // The partial tail is always the highest index; if it's below the
        // minimum, stop here WITHOUT advancing the index, so we never mark a
        // real chunk as flushed.
        if (minutes < MIN_PARTIAL_MINUTES) break;

        const result = await this.postChunk(state, idx, minutes);
        if (result.ok) {
          state.lastFlushedChunkIndex = idx;
          await this.persist();
          // Mirror the chunk into the local dashboard history (heatmap / games) —
          // but skip a dedup replay (server said alreadyAwarded) so a re-sent chunk
          // after a service-worker restart never double-counts the local series.
          if (this.history && !result.dup) {
            recordChunk(this.history, {
              placeId: state.placeId,
              minutes,
              xp: Math.round(minutes * XP_PER_MINUTE),
              when: Date.now(),
            });
            await this.persistHistory();
          }
        } else {
          break; // network/server error — retry on a later poll
        }
      }
    } catch (error) {
      console.error("[PLAYTIME] flush error:", error);
    } finally {
      this.flushing = false;
    }
  }

  async postChunk(state, chunkIndex, minutes, isRetry = false) {
    try {
      if (!this.accessToken) {
        const auth = await getAuthToken();
        this.accessToken = (auth && auth.accessToken) || null;
      }
      if (!this.accessToken) return { ok: false, dup: false };

      const res = await fetch(`${API_BASE_URL}/api/playtime/chunk`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${this.accessToken}`,
        },
        body: JSON.stringify({
          sessionId: state.sessionId,
          chunkIndex,
          placeId: state.placeId || undefined,
          gameId: state.gameId || undefined,
          minutes,
          source: "extension",
        }),
      });

      if (res.ok) {
        // 200 always advances the index. Read the body to tell a fresh award from
        // a dedup replay (alreadyAwarded) so the caller skips re-recording local
        // history. A deferred/capped chunk is NOT a dup — it's real play time.
        let data = null;
        try {
          data = await res.json();
        } catch (_) {
          /* empty/non-JSON body — treat as a fresh award */
        }
        return { ok: true, dup: !!(data && data.alreadyAwarded) };
      }
      // Legacy: older servers signalled a duplicate with 409 (now 200+alreadyAwarded).
      if (res.status === 409) return { ok: true, dup: true };

      if (res.status === 401 && !isRetry) {
        this.accessToken = null;
        const auth = await getAuthToken();
        this.accessToken = (auth && auth.accessToken) || null;
        if (this.accessToken) {
          return this.postChunk(state, chunkIndex, minutes, true);
        }
      }

      console.warn("[PLAYTIME] chunk flush failed:", res.status);
      return { ok: false, dup: false };
    } catch (error) {
      console.warn("[PLAYTIME] chunk flush network error:", error.message);
      return { ok: false, dup: false };
    }
  }

  /** Tell the theme (roblox.com tabs) to show the game-close XP summary. */
  async broadcastSessionComplete(summary) {
    try {
      const tabs = await chrome.tabs.query({ url: "*://*.roblox.com/*" });
      if (tabs && Array.isArray(tabs)) {
        tabs.forEach(async (tab) => {
          try {
            await chrome.tabs.sendMessage(tab.id, {
              type: "PLAYTIME_SESSION_COMPLETE",
              data: summary,
            });
          } catch (error) {}
        });
      }
    } catch (error) {}
  }

  /** Current live session snapshot — used by the theme for an in-game widget. */
  async getCurrentSession() {
    if (!this.loaded) await this.init();
    if (!this.state) return { inGame: false };
    const s = this.state;
    return {
      inGame: true,
      sessionId: s.sessionId,
      placeId: s.placeId,
      gameName: s.gameName,
      startedAt: s.startedAt,
      accruedMs: s.accruedMs,
      xpEarned: Math.floor((s.accruedMs / 60000) * XP_PER_MINUTE),
    };
  }

  async persist() {
    if (this.state) await storageManager.set(SESSION_KEY, this.state);
  }

  async clear() {
    this.state = null;
    await storageManager.set(SESSION_KEY, null);
  }
}

const playtimeXpService = new PlaytimeXpService();
export default playtimeXpService;
